import assert from "node:assert/strict";
import { test } from "node:test";
import { CREATURES } from "../../dist/public/sim/data/creatures.js";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import { resolveCombat } from "../../dist/public/sim/combat.js";
import { newMapRun } from "../../dist/public/sim/run.js";
import { programFromRules } from "./program-fixture.mjs";

const [mapId, map] = Object.entries(MAPS)[0];

function encounter(action, backpack = {}) {
  const program = programFromRules({
    condition: { kind: "always" },
    action: { kind: action },
  });
  const run = newMapRun(map, 1, program, { mapId, characterId: 1 }).run;
  return {
    run: {
      ...run,
      character: {
        ...run.character,
        backpack: { ...run.character.backpack, ...backpack },
      },
    },
    program,
  };
}

function runWithProgram(program, backpack = {}) {
  const run = newMapRun(map, 1, program, { mapId, characterId: 1 }).run;
  return {
    ...run,
    character: {
      ...run.character,
      backpack: { ...run.character.backpack, ...backpack },
    },
  };
}

test("four stick strikes defeat the wolf after three bites, leaving 79 health", () => {
  const { run, program } = encounter("strikeWithStick", { stick: 1 });
  const runBefore = structuredClone(run);
  const programBefore = structuredClone(program);
  const mapBefore = structuredClone(map);
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.creatureHealth, 0);
  assert.equal(result.characterHealth, 79);
  assert.equal(result.outcome, "creatureDefeated");
  assert.equal(result.exchanges.length, 4);
  assert.equal(result.exchanges[3].creatureAction.kind, "dodge");
  assert.equal(result.ruleStarts[1], 4);
  assert.equal(run.body.health, 100);
  assert.equal(run.character.backpack.stick, 1);
  assert.deepEqual(run, runBefore);
  assert.deepEqual(program, programBefore);
  assert.deepEqual(map, mapBefore);
  assert.equal(CREATURES.wolf.health, 24);
});

test("eight kicks defeat the wolf after six bites, leaving 58 health", () => {
  const { run, program } = encounter("kick");
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.creatureHealth, 0);
  assert.equal(result.characterHealth, 58);
  assert.equal(result.outcome, "creatureDefeated");
  assert.equal(result.exchanges.length, 8);
});

test("no feasible combat rule loses each action and the fifteenth bite kills", () => {
  const program = programFromRules();
  const run = runWithProgram(program);
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.outcome, "characterDied");
  assert.equal(result.characterHealth, 0);
  assert.equal(result.creatureHealth, 24);
  assert.equal(result.exchanges.length, 15);
  assert.ok(
    result.exchanges.every((exchange) => exchange.characterAction === null),
  );
  assert.deepEqual(result.ruleStarts, {});
});

test("a lethal opening strike ends the exchange before the character can act", () => {
  const { run, program } = encounter("kick");
  const woundedRun = { ...run, body: { ...run.body, health: 7 } };
  const result = resolveCombat(woundedRun, map, "wolf", program);

  assert.equal(result.outcome, "characterDied");
  assert.equal(result.characterHealth, 0);
  assert.equal(result.exchanges.length, 1);
  assert.equal(result.exchanges[0].characterAction, null);
  assert.deepEqual(result.ruleStarts, {});
});

test("forty dodges use one refreshed reduction and leave the wolf at 15 health", () => {
  const { run, program } = encounter("dodge");
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.outcome, "creatureDeparted");
  assert.equal(result.creatureHealth, 24);
  assert.equal(result.characterHealth, 15);
  assert.equal(result.exchanges.length, 40);
  assert.equal(result.exchanges[0].creatureAction.damage, 7);
  assert.ok(
    result.exchanges
      .slice(1)
      .every((exchange) => exchange.creatureAction.damage === 2),
  );
});

test("a stick strike without a stick is skipped in favor of the next combat rule", () => {
  const program = programFromRules(
    { condition: { kind: "always" }, action: { kind: "strikeWithStick" } },
    { condition: { kind: "always" }, action: { kind: "kick" } },
  );
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.deepEqual(result.exchanges[0].characterAction, {
    ruleId: 2,
    action: { kind: "kick" },
    damage: 3,
    creatureHealth: 21,
    characterHealth: 93,
  });
  assert.deepEqual(result.ruleStarts, { 2: 8 });
});

test("ordinary actions cannot be carried out during combat", () => {
  const program = programFromRules({
    condition: { kind: "always" },
    action: { kind: "explore" },
  });
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.equal(result.exchanges[0].characterAction, null);
  assert.deepEqual(result.ruleStarts, {});
});

test("character health conditions are checked after the creature's strike", () => {
  const program = programFromRules({
    condition: { kind: "healthBelow", value: 94 },
    action: { kind: "kick" },
  });
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.equal(result.exchanges[0].creatureAction.characterHealth, 93);
  assert.equal(result.exchanges[0].characterAction.action.kind, "kick");
  assert.equal(result.ruleStarts[1], 8);
});

test("combat checks group conditions in order against post-strike health", () => {
  const always = { kind: "always" };
  const kick = { kind: "kick" };
  const program = {
    groups: [
      {
        id: 1,
        name: "Wounded",
        condition: { kind: "healthBelow", value: 94 },
        rules: [{ id: 11, condition: always, action: kick }],
      },
      {
        id: 2,
        name: "Fallback",
        condition: always,
        rules: [{ id: 22, condition: always, action: kick }],
      },
    ],
    nextGroupId: 3,
    nextRuleId: 23,
  };
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.equal(result.exchanges[0].characterAction.ruleId, 11);
  assert.equal(result.ruleStarts[11], 8);
  assert.equal(result.ruleStarts[22], undefined);
});

// Invariant program-rule-pick: a false group must be skipped, while a true
// earlier group wins. The first bite leaves 100 - 7 = 93 health.
// Sources: foundations/decisions.md:476 (D-23), :2590 (D-144).
test("combat skips a false first group and selects it when its condition holds", () => {
  for (const [threshold, expectedAction, expectedWolfHealth] of [
    [50, "kick", 21],
    [94, "dodge", 24],
  ]) {
    const program = {
      groups: [
        {
          id: 1,
          name: "Wounded",
          condition: { kind: "healthBelow", value: threshold },
          rules: [
            { id: 1, condition: { kind: "always" }, action: { kind: "dodge" } },
          ],
        },
        {
          id: 2,
          name: "Fallback",
          condition: { kind: "always" },
          rules: [
            { id: 2, condition: { kind: "always" }, action: { kind: "kick" } },
          ],
        },
      ],
      nextGroupId: 3,
      nextRuleId: 3,
    };
    const result = resolveCombat(runWithProgram(program), map, "wolf", program);
    const first = result.exchanges[0];
    assert.equal(first.creatureAction.characterHealth, 93);
    assert.equal(first.characterAction.action.kind, expectedAction);
    assert.equal(first.characterAction.creatureHealth, expectedWolfHealth);
  }
});

// Invariant program-rule-pick: a false rule passes to the next rule within the
// same group. The wolf still has 24 health before the character's first action.
// Sources: foundations/decisions.md:476 (D-23), :2590 (D-144).
test("combat skips a false first rule and selects it when its condition holds", () => {
  for (const [threshold, expectedAction, expectedWolfHealth] of [
    [10, "kick", 21],
    [25, "dodge", 24],
  ]) {
    const program = programFromRules(
      {
        condition: { kind: "opponentHealthBelow", value: threshold },
        action: { kind: "dodge" },
      },
      { condition: { kind: "always" }, action: { kind: "kick" } },
    );
    const result = resolveCombat(runWithProgram(program), map, "wolf", program);
    assert.equal(
      result.exchanges[0].characterAction.action.kind,
      expectedAction,
    );
    assert.equal(
      result.exchanges[0].characterAction.creatureHealth,
      expectedWolfHealth,
    );
  }
});

tests/sim/completion.test.mjs.source:
// The completion of a map run: when the streak reaches the solving condition of the map, the rest of
// that game minute takes effect, no program rule is picked and the map run ends, solving its map.
// Expectations come from the task "rozwiazanie-lasu", To do 5 and 7 and Questions to settle 6, 8,
// 15 and 17 (task.md lines 19-22, 42-50, 66-71, 75-77); the streak of 480 is the solving condition
// of Las (D-80), a streak of 479 stands one game minute short of it.
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  advanceMinutes,
  canSendMap,
  createCharacter,
  end,
  newGame,
  passRealTime,
  restart,
  send,
  setProgram,
} from "../../dist/public/sim/game.js";
import { sameHex } from "../../dist/public/sim/hex.js";
import { meetsSolving } from "../../dist/public/sim/run.js";
import { programFromRules } from "./program-fixture.mjs";
import { newKnowingGame } from "./understanding-fixture.mjs";

const [mapId] = Object.keys(MAPS);
const SENT = { mapId, characterId: 1 };
const REAL_MS = 1760000000000;
const EXPLORING = programFromRules({
  condition: { kind: "always" },
  action: { kind: "explore" },
});
const EXPLORE = { kind: "explore" };
const HEALTHY = { temperature: 37, satiety: 100, health: 100 };

/** A game sent to Las with a program that explores; the map run stands at minute 0. */
function sent(game = newKnowingGame()) {
  const ready = createCharacter(setProgram(game, EXPLORING).state, "Ala").state;
  return send(ready, SENT, REAL_MS).state;
}

/** The sent game with the fields of its map run replaced. */
function withRun(fields, game) {
  const state = sent(game);
  return { ...state, run: { ...state.run, ...fields } };
}

/** The explore activity of the map run, ending in the next game minute. */
function endingNext(run) {
  return {
    activity: { kind: "rule", ruleId: 1, action: EXPLORE },
    startMinute: run.minute,
    endMinute: run.minute + 1,
    stepTo: null,
  };
}

/** A healthy map run whose streak stands at 479 and whose exploration ends in the next minute. */
function oneShort(game) {
  const run = sent(game).run;
  return withRun(
    { body: { ...HEALTHY }, streak: 479, current: endingNext(run) },
    game,
  );
}

/** A tile that is not the character's, for a campfire burning away from it. */
function otherTile(run) {
  return run.tiles.find((tile) => !sameHex(tile.at, run.character.at)).at;
}

const kinds = (events) => events.map((event) => event.kind);

test("a map run with a streak of 479 completes at the end of the next game minute without a loss, with the rest of that minute taken effect and no program rule picked", () => {
  const before = oneShort();
  const at = otherTile(before.run);
  const state = {
    ...before,
    run: { ...before.run, campfires: [{ at, minutesLeft: 10 }] },
  };
  const result = advanceMinutes(state, 5);
  const run = result.state.run;
  assert.equal(run.minute, 1, "the span stops at the completion");
  assert.equal(run.streak, 480);
  assert.deepEqual(run.completion, { minute: 1 });
  assert.equal(run.death, null);
  assert.deepEqual(
    run.campfires,
    [{ at, minutesLeft: 9 }],
    "burning took its minute",
  );
  assert.deepEqual(
    run.current,
    before.run.current,
    "no program rule was picked",
  );
  assert.deepEqual(result.events, [
    {
      kind: "activityFinished",
      minute: 1,
      activity: before.run.current.activity,
    },
    { kind: "tileRevealed", minute: 1, at: before.run.character.at },
    { kind: "mapRunCompleted", minute: 1 },
  ]);
  assert.ok(!kinds(result.events).includes("activityStarted"));
  assert.equal(result.state.paused, false);
  assert.equal(result.state.discovery, null);
  assert.deepEqual(result.state.solvedMaps, [mapId]);
});

test("a streak of 478 completes nothing in the next minute and the pick goes on", () => {
  const state = { ...oneShort(), run: { ...oneShort().run, streak: 478 } };
  const result = advanceMinutes(state, 1);
  assert.equal(result.state.run.streak, 479);
  assert.equal(result.state.run.completion, null);
  assert.deepEqual(result.state.solvedMaps, []);
  assert.ok(kinds(result.events).includes("activityStarted"));
});

test("a minute of loss from a streak of 479 does not complete", () => {
  const state = withRun({
    body: { temperature: 34.99, satiety: 100, health: 100 },
    streak: 479,
  });
  const result = advanceMinutes(state, 1);
  assert.equal(result.state.run.streak, 0);
  assert.equal(result.state.run.completion, null);
  assert.deepEqual(result.state.solvedMaps, []);
});

test("a new game and a new map run hold no completion and no solved map", () => {
  assert.deepEqual(newGame().solvedMaps, []);
  assert.equal(sent().run.completion, null);
});

test("a map run that has completed passes no further game minute, by span or by real time", () => {
  const done = advanceMinutes(oneShort(), 1).state;
  const again = advanceMinutes(done, 10);
  assert.deepEqual(again.state, done);
  assert.deepEqual(again.events, []);
  const timed = passRealTime(done, 60000);
  assert.deepEqual(timed.state, done);
  assert.deepEqual(timed.events, []);
});

test("real time that ends in a completion stops there and drops the whole carry", () => {
  const state = { ...oneShort(), realMsCarry: 400 };
  const result = passRealTime(state, 5600);
  assert.equal(result.state.run.minute, 1);
  assert.deepEqual(result.state.run.completion, { minute: 1 });
  assert.equal(result.state.realMsCarry, 0);
  assert.equal(result.events.at(-1).kind, "mapRunCompleted");
  assert.equal(result.state.paused, false);
});

test("the completion in the minute of a discovery leaves the state holding the discovery, not paused", () => {
  const unknowing = {
    ...newGame(),
    understanding: {
      actions: [],
      conditions: ["always"],
      items: [],
      creatures: [],
    },
  };
  const result = advanceMinutes(oneShort(unknowing), 5);
  const found = result.events.findIndex((event) => event.kind === "discovered");
  const completed = result.events.findIndex(
    (event) => event.kind === "mapRunCompleted",
  );
  assert.ok(found >= 0, "precondition: the minute discovered something");
  assert.ok(completed > found, "the completion follows the discovery");
  assert.equal(result.events.length, completed + 1);
  assert.equal(result.state.run.minute, 1);
  assert.deepEqual(result.state.run.completion, { minute: 1 });
  assert.equal(result.state.paused, false);
  assert.deepEqual(result.state.discovery, {
    actions: result.events[found].actions,
    conditions: result.events[found].conditions,
    items: result.events[found].items,
    creatures: [],
  });
  const revealed = result.events[found];
  for (const kind of ["actions", "conditions", "items"])
    for (const entry of revealed[kind])
      assert.ok(result.state.understanding[kind].includes(entry), entry);
  assert.deepEqual(result.state.solvedMaps, [mapId]);
});

test("a map solved stays solved, once, through restart, end, send and a later death", () => {
  const solved = advanceMinutes(oneShort(), 1).state;
  assert.deepEqual(restart(solved).state.solvedMaps, [mapId]);
  const ended = end(solved).state;
  assert.deepEqual(ended.solvedMaps, [mapId]);
  assert.deepEqual(send(ended, SENT, REAL_MS).state.solvedMaps, [mapId]);

  // A later map run on the same map completes again and the map is listed once.
  const second = restart(solved).state;
  const again = {
    ...second,
    run: {
      ...second.run,
      body: { ...HEALTHY },
      streak: 479,
      current: endingNext(second.run),
    },
  };
  assert.deepEqual(advanceMinutes(again, 1).state.solvedMaps, [mapId]);

  // A later map run that ends in death leaves the map solved.
  const dying = {
    ...second,
    run: {
      ...second.run,
      body: { temperature: 34, satiety: 50, health: 0.7 },
      streak: 5,
    },
  };
  const died = advanceMinutes(dying, 30).state;
  assert.ok(died.run.death);
  assert.equal(died.run.completion, null);
  assert.deepEqual(died.solvedMaps, [mapId]);
});

test("restart after a completion keeps the seed and starts with a streak of 0 and no completion", () => {
  const solved = advanceMinutes(oneShort(), 1).state;
  const restarted = restart(solved);
  assert.equal(restarted.state.run.seed, solved.run.seed);
  assert.equal(restarted.state.run.minute, 0);
  assert.equal(restarted.state.run.streak, 0);
  assert.equal(restarted.state.run.completion, null);
  assert.equal(restarted.state.paused, false);
  assert.equal(restarted.events[0].kind, "mapRunEnded");
});

test("the counts of the rules stay after a completion, through end", () => {
  const state = oneShort();
  assert.deepEqual(state.ruleCounts, { 1: 1 });
  const solved = advanceMinutes(state, 1).state;
  assert.deepEqual(solved.ruleCounts, { 1: 1 });
  assert.deepEqual(end(solved).state.ruleCounts, { 1: 1 });
});

test("the program edited on a map run that has completed leaves its streak at 480", () => {
  const solved = advanceMinutes(oneShort(), 1).state;
  const edited = setProgram(
    solved,
    programFromRules(
      { condition: { kind: "always" }, action: { kind: "explore" } },
      { condition: { kind: "always" }, action: { kind: "wander" } },
    ),
  ).state;
  assert.equal(edited.run.streak, 480);
  assert.deepEqual(edited.run.completion, { minute: 1 });
});

test("solving requirements present in data are all required and absent ones are ignored", () => {
  const deep = MAPS.forestDeep;
  const run = {
    ...sent().run,
    mapId: "forestDeep",
    streak: 539,
    defeatedAttacks: 1,
  };
  assert.equal(meetsSolving(run, deep), false);
  assert.equal(meetsSolving({ ...run, streak: 540 }, deep), false);
  assert.equal(meetsSolving({ ...run, defeatedAttacks: 2 }, deep), false);
  assert.equal(
    meetsSolving({ ...run, streak: 540, defeatedAttacks: 2 }, deep),
    true,
  );
  assert.equal(
    meetsSolving(
      { ...run, defeatedAttacks: 1 },
      { ...deep, solving: { defeatedAttacks: 2 } },
    ),
    false,
  );
  assert.equal(
    meetsSolving(
      { ...run, defeatedAttacks: 2 },
      { ...deep, solving: { defeatedAttacks: 2 } },
    ),
    true,
  );
  assert.equal(meetsSolving({ ...run, streak: 480 }, MAPS.forest), true);
});

test("a map is sendable only after each map it opens after is solved", () => {
  assert.deepEqual(canSendMap([], "forest"), true);
  assert.deepEqual(canSendMap([], "forestDeep"), false);
  assert.deepEqual(canSendMap(["forest"], "forestDeep"), true);
  assert.throws(
    () =>
      send(
        createCharacter(newGame(), "Ala").state,
        { mapId: "forestDeep", characterId: 1 },
        REAL_MS,
      ),
    /not available/,
  );
});

test("an actual program edit resets the streak and defeated attacks; cold loss keeps defeated attacks", () => {
  const prepared = { ...end(sent()).state, solvedMaps: ["forest"] };
  const deeper = send(
    prepared,
    { mapId: "forestDeep", characterId: 1 },
    REAL_MS,
  ).state;
  const progressed = {
    ...deeper,
    run: {
      ...deeper.run,
      streak: 120,
      defeatedAttacks: 1,
      body: { ...HEALTHY, temperature: 34.99 },
    },
  };
  const changed = setProgram(
    progressed,
    programFromRules({
      condition: { kind: "always" },
      action: { kind: "wander" },
    }),
  ).state;
  assert.equal(changed.run.streak, 0);
  assert.equal(changed.run.defeatedAttacks, 0);

  const lostHealth = advanceMinutes(progressed, 1).state;
  assert.equal(lostHealth.run.streak, 0);
  assert.equal(lostHealth.run.defeatedAttacks, 1);
});

tests/sim/conditions.test.mjs.source:
import assert from "node:assert/strict";
import { test } from "node:test";
import { ITEMS } from "../../dist/public/sim/data/items.js";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  neighbours,
  offsetToAxial,
  sameHex,
} from "../../dist/public/sim/hex.js";
import {
  createCharacter,
  newGame,
  send,
  setProgram,
} from "../../dist/public/sim/game.js";
import { conditionHolds } from "../../dist/public/sim/program.js";
import { newMapRun } from "../../dist/public/sim/run.js";
import { programFromRules, programRules } from "./program-fixture.mjs";

// The conditions on the body, the backpack and the campfire (task, To do 12–13; spec Decision 3;
// D-26, D-57). Every number below is written out by hand from the spec's table: „Temperatura
// poniżej” takes 30.0 to 37.0 °C in steps of 0.1, „Sytość poniżej” 0 to 100 %, „Zapas poniżej”
// 0 to 50 pieces, „Zostało mniej niż — ognisko” 0 to 120 minutes and „Tu leży mniej niż” 0 to 50
// pieces, each of these four in steps of 1; „Z dala od — ognisko” takes no number.

const [mapId, forest] = Object.entries(MAPS)[0];
// The first character a new game creates takes the id 1.
const characterId = 1;
const [resource] = forest.resources.map((each) => each.id);
const [firstItem, secondItem] = Object.keys(ITEMS);
const entrance = offsetToAxial(forest.entrance.col, forest.entrance.row);
const SENT = { mapId, characterId };
const REAL_MS = 1760000000000;

const ALWAYS = { kind: "always" };
const EXPLORE = { kind: "explore" };
const rule = (condition, action) => ({ condition, action });
const temperatureBelow = (value) => ({ kind: "temperatureBelow", value });
const satietyBelow = (value) => ({ kind: "satietyBelow", value });
const natureEnergyBelow = (value) => ({ kind: "natureEnergyBelow", value });
const itemBelow = (item, value) => ({ kind: "itemBelow", item, value });
const campfireLeftBelow = (value) => ({ kind: "campfireLeftBelow", value });
const healthBelow = (value) => ({ kind: "healthBelow", value });
const opponentHealthBelow = (value) => ({ kind: "opponentHealthBelow", value });
const AWAY = { kind: "awayFromCampfire" };
const hereBelow = (value) => ({ kind: "hereBelow", resource, value });

/** A map run of Las at minute 0 with no program rules, with the given fields replaced. */
function handMade(fields = {}) {
  const { run } = newMapRun(forest, 3, programFromRules(), {
    mapId,
    characterId,
  });
  return { ...run, ...fields };
}

const withBody = (temperature, satiety) =>
  handMade({ body: { temperature, satiety, health: 100 } });

/** A run whose backpack holds the given pieces and nothing else. */
function carrying(pieces) {
  const run = handMade();
  const empty = Object.fromEntries(
    Object.keys(run.character.backpack).map((id) => [id, 0]),
  );
  return {
    ...run,
    character: { ...run.character, backpack: { ...empty, ...pieces } },
  };
}

const holds = (run, condition) => conditionHolds(run, forest, condition);

test("health conditions compare the acting side and its opponent in health points", () => {
  const woundedWolf = { health: 6, opponentHealth: 100 };
  assert.equal(
    conditionHolds(handMade(), forest, healthBelow(8), woundedWolf),
    true,
  );
  assert.equal(
    conditionHolds(handMade(), forest, healthBelow(6), woundedWolf),
    false,
    "the threshold is strict",
  );
  assert.equal(
    conditionHolds(handMade(), forest, opponentHealthBelow(101), woundedWolf),
    true,
  );
  assert.equal(
    conditionHolds(handMade(), forest, opponentHealthBelow(100), woundedWolf),
    false,
    "the opponent threshold is strict",
  );
  assert.equal(holds(withBody(37, 100), healthBelow(101)), true);
  assert.equal(holds(handMade(), opponentHealthBelow(101)), false);
});

test("„Temperatura poniżej N °C” holds below N and not at N, also for tenths", () => {
  assert.equal(holds(withBody(34.999999, 100), temperatureBelow(35)), true);
  assert.equal(holds(withBody(35, 100), temperatureBelow(35)), false);
  assert.equal(holds(withBody(36.59, 100), temperatureBelow(36.6)), true);
  assert.equal(holds(withBody(36.6, 100), temperatureBelow(36.6)), false);
  assert.equal(holds(withBody(36.61, 100), temperatureBelow(36.6)), false);
});

test("„Sytość poniżej N %” holds below N and not at N", () => {
  assert.equal(holds(withBody(37, 29.999999), satietyBelow(30)), true);
  assert.equal(holds(withBody(37, 30), satietyBelow(30)), false);
  assert.equal(holds(withBody(37, 0), satietyBelow(0)), false);
  assert.equal(holds(withBody(37, 100), satietyBelow(100)), false);
  assert.equal(holds(withBody(37, 99.4), satietyBelow(100)), true);
});

test("„Energia natury poniżej N” reads the mage's nature energy, holding below N and not at N", () => {
  // Task plomyk, To do 5 (plomyk_loop2.md:22). The body is full: the energy alone decides.
  const energy = (natureEnergy) => handMade({ natureEnergy });
  assert.equal(holds(energy(29.5), natureEnergyBelow(30)), true);
  assert.equal(holds(energy(30), natureEnergyBelow(30)), false);
  assert.equal(holds(energy(0), natureEnergyBelow(0)), false);
  assert.equal(holds(energy(0), natureEnergyBelow(1)), true);
  assert.equal(holds(energy(100), natureEnergyBelow(100)), false);
});

test("„Zapas poniżej N szt.” counts only the named item of the backpack", () => {
  assert.equal(
    holds(carrying({ [firstItem]: 2 }), itemBelow(firstItem, 3)),
    true,
  );
  assert.equal(
    holds(carrying({ [firstItem]: 3 }), itemBelow(firstItem, 3)),
    false,
  );
  assert.equal(
    holds(carrying({ [secondItem]: 9 }), itemBelow(firstItem, 1)),
    true,
    "pieces of another item do not count",
  );
  assert.equal(
    holds(carrying({ [firstItem]: 9 }), itemBelow(secondItem, 1)),
    true,
  );
  assert.equal(holds(carrying({}), itemBelow(firstItem, 0)), false);
});

test("„Zostało mniej niż N min — ognisko” reads 0 where there is no campfire", () => {
  assert.equal(holds(handMade(), campfireLeftBelow(1)), true);
  assert.equal(holds(handMade(), campfireLeftBelow(0)), false);
});

test("„Zostało mniej niż N min — ognisko” reads the minutes left to a campfire on the character's tile", () => {
  const here = (minutesLeft) =>
    handMade({ campfires: [{ at: entrance, minutesLeft }] });
  assert.equal(holds(here(20), campfireLeftBelow(20)), false);
  assert.equal(holds(here(20), campfireLeftBelow(21)), true);
  assert.equal(holds(here(0), campfireLeftBelow(1)), true, "extinguished");
  assert.equal(holds(here(0), campfireLeftBelow(0)), false);
});

test("„Zostało mniej niż N min — ognisko” reads the nearest campfire, extinguished or not, not a farther one", () => {
  // Every tile costs 10 minutes to enter, so the neighbour is the nearer of the two.
  const run = handMade();
  const tiles = run.tiles.map((tile) => ({ ...tile, stepMinutes: 10 }));
  const [near] = neighbours(tiles, entrance);
  const far = tiles.find(
    (tile) =>
      !sameHex(tile.at, entrance) &&
      !neighbours(tiles, entrance).some((n) => sameHex(n.at, tile.at)),
  );
  const fires = (nearMinutes, farMinutes) =>
    handMade({
      tiles,
      campfires: [
        { at: far.at, minutesLeft: farMinutes },
        { at: near.at, minutesLeft: nearMinutes },
      ],
    });
  assert.equal(holds(fires(5, 100), campfireLeftBelow(6)), true);
  assert.equal(holds(fires(5, 100), campfireLeftBelow(5)), false);
  assert.equal(
    holds(fires(0, 100), campfireLeftBelow(1)),
    true,
    "the nearest is extinguished, a farther one burns",
  );
  assert.equal(holds(fires(100, 0), campfireLeftBelow(100)), false);
});

test("„Zostało mniej niż N min — ognisko” counts nearness in game minutes of walking, not in tiles", () => {
  // Every tile costs 10 minutes to enter but the neighbour `slow`, which costs 100: a tile two
  // tiles away through another neighbour is 20 minutes away, `slow` 100.
  const run = handMade();
  const [slow, other] = neighbours(run.tiles, entrance);
  const twoAway = neighbours(run.tiles, other.at).find(
    (tile) =>
      !sameHex(tile.at, entrance) &&
      !neighbours(run.tiles, entrance).some((n) => sameHex(n.at, tile.at)),
  );
  const tiles = run.tiles.map((tile) => ({
    ...tile,
    stepMinutes: sameHex(tile.at, slow.at) ? 100 : 10,
  }));
  const fires = handMade({
    tiles,
    campfires: [
      { at: slow.at, minutesLeft: 5 },
      { at: twoAway.at, minutesLeft: 60 },
    ],
  });
  assert.equal(holds(fires, campfireLeftBelow(60)), false);
  assert.equal(holds(fires, campfireLeftBelow(61)), true);
});

test("„Z dala od — ognisko” holds where no campfire stands on the character's tile", () => {
  const [near] = neighbours(handMade().tiles, entrance);
  assert.equal(holds(handMade(), AWAY), true, "no campfire");
  assert.equal(
    holds(handMade({ campfires: [{ at: near.at, minutesLeft: 30 }] }), AWAY),
    true,
    "a campfire on a neighbouring tile",
  );
  for (const minutesLeft of [0, 30]) {
    assert.equal(
      holds(handMade({ campfires: [{ at: entrance, minutesLeft }] }), AWAY),
      false,
      `a campfire with ${minutesLeft} minutes on the character's tile`,
    );
  }
});

/** The program a game state holds: the copy during a map run, else the only program of the list (task, To do 1 and 7). */
function heldProgram(state) {
  return state.run === null
    ? state.programs[0].program
    : state.run.copy.program;
}

/** The program `setProgram` holds after taking `condition` in, on the sending screen and in a run. */
function held(condition) {
  const program = programFromRules(rule(condition, EXPLORE));
  const running = send(
    createCharacter(newGame(), "Ala").state,
    SENT,
    REAL_MS,
  ).state;
  return [newGame(), running].map(
    (state) =>
      programRules(heldProgram(setProgram(state, program).state))[0].condition,
  );
}

function refused(condition) {
  const running = send(
    createCharacter(newGame(), "Ala").state,
    SENT,
    REAL_MS,
  ).state;
  for (const state of [newGame(), running]) {
    assert.throws(
      () => setProgram(state, programFromRules(rule(condition, EXPLORE))),
      Error,
      JSON.stringify(condition),
    );
  }
}

test("the check takes a temperature with tenths and holds it as the decimal the player reads", () => {
  for (const [offered, kept] of [
    [36.6, 36.6],
    [30.0, 30],
    [37, 37],
    [36.5, 36.5],
    [36.60000000000001, 36.6],
    [30.000000000000004, 30],
  ]) {
    for (const condition of held(temperatureBelow(offered))) {
      assert.deepEqual(condition, temperatureBelow(kept), String(offered));
      assert.equal(String(condition.value), String(kept));
    }
  }
});

test("the check refuses a temperature off the step of 0.1 or outside 30.0–37.0", () => {
  for (const value of [36.55, 29.9, 37.1, 36.61, -1, 100]) {
    refused(temperatureBelow(value));
  }
});

test("the check takes the whole numbers of „Tu leży mniej niż” as before, and only those", () => {
  for (const value of [0, 1, 7, 50]) {
    for (const condition of held(hereBelow(value)))
      assert.deepEqual(condition, hereBelow(value));
  }
  for (const value of [1.5, 0.1, -1, 51]) refused(hereBelow(value));
});

test("the check takes each new kind's numbers from its minimum to its maximum on its step", () => {
  const ranges = [
    [satietyBelow, 0, 100],
    // Task plomyk, To do 5 (plomyk_loop2.md:22): from 0 to 100 by 1.
    [natureEnergyBelow, 0, 100],
    [healthBelow, 0, 100],
    [opponentHealthBelow, 0, 100],
    [(value) => itemBelow(firstItem, value), 0, 50],
    [campfireLeftBelow, 0, 120],
  ];
  for (const [make, min, max] of ranges) {
    for (const value of [min, max, min + 1, max - 1]) {
      for (const condition of held(make(value)))
        assert.deepEqual(condition, make(value));
    }
    for (const value of [min - 1, max + 1, min + 0.5, max - 0.1]) {
      refused(make(value));
    }
  }
});

test("the check refuses a number that is no finite number, for every kind that takes one", () => {
  const makers = [
    temperatureBelow,
    satietyBelow,
    natureEnergyBelow,
    healthBelow,
    opponentHealthBelow,
    (value) => itemBelow(firstItem, value),
    campfireLeftBelow,
    hereBelow,
  ];
  for (const make of makers) {
    for (const value of [
      Number.NaN,
      Infinity,
      -Infinity,
      "20",
      null,
      undefined,
    ])
      refused(make(value));
  }
});

test("„Zapas poniżej” takes every item of the data, and nothing else", () => {
  for (const item of Object.keys(ITEMS)) {
    for (const condition of held(itemBelow(item, 8)))
      assert.deepEqual(condition, itemBelow(item, 8));
  }
  for (const item of ["granite", "toString", "", 0, undefined]) {
    refused(itemBelow(item, 8));
  }
});

test("„Z dala od — ognisko” takes no number and no target", () => {
  for (const condition of held(AWAY)) assert.deepEqual(condition, AWAY);
  for (const condition of held({ ...AWAY, value: 3 }))
    assert.deepEqual(condition, AWAY);
  for (const condition of held(ALWAYS)) assert.deepEqual(condition, ALWAYS);
});

tests/sim/copy-actions.test.mjs.source:
// The operations on a manual map run's copy: the two measures of its record, the saves, the
// discard and the switch. Expectations come from the task "programy-gracza", the vault file
// `programy_gracza_loop2.md` (To do 6 to 12), and from D-93, D-131, D-136, D-164, D-171 and D-174
// in foundations/decisions.md. Every expected value is written out here.
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  advanceMinutes,
  createCharacter,
  newGame,
  send,
  setPaused,
  setProgram,
} from "../../dist/public/sim/game.js";
import {
  copyHasUnsavedChanges,
  deleteProgram,
  discardCopyChanges,
  editProgram,
  programHasChangesCopyLacks,
  saveCopyAsNewProgram,
  saveCopyIntoProgram,
  switchProgram,
} from "../../dist/public/sim/programs.js";
import { programFromRules } from "./program-fixture.mjs";
import { newKnowingGame } from "./understanding-fixture.mjs";

const MAP_ID = Object.keys(MAPS)[0];
const REAL_MS = 1760000000000;
const ALWAYS = { kind: "always" };
const rule = (condition, action) => ({ condition, action });
const EXPLORING = programFromRules(rule(ALWAYS, { kind: "explore" }));
const WANDERING = programFromRules(rule(ALWAYS, { kind: "wander" }));
// Rule 1 explores for 20 game minutes, which covers the 10 the scenarios pass; rule 2 is never reached.
const EXPLORING_THEN_WANDERING = programFromRules(
  rule(ALWAYS, { kind: "explore" }),
  rule(ALWAYS, { kind: "wander" }),
);
const DEATH = { minute: 10, cause: "cold" };

/** A knowing game with Ala (1) and the program 1 holding `program`. */
function ready(program) {
  const made = createCharacter(newKnowingGame(), "Ala").state;
  return editProgram(made, 1, program).state;
}

/** Ala sent with program 1 holding `program`, nothing edited. */
function sentWith(program) {
  return send(
    ready(program),
    { mapId: MAP_ID, characterId: 1, programId: 1 },
    REAL_MS,
  ).state;
}

/** Ala sent with program 1 holding EXPLORING, her copy edited to EXPLORING_THEN_WANDERING, 10 minutes on. */
function editedAndRunning() {
  const edited = setProgram(sentWith(EXPLORING), EXPLORING_THEN_WANDERING);
  return advanceMinutes(edited.state, 10).state;
}

/** The state with the programs 3 (wandering) and 4 (exploring) beside program 1; 2 stands for a deleted one. */
function withOthers(state) {
  return {
    ...state,
    programs: [
      state.programs[0],
      { id: 3, name: "Wędrówka", program: WANDERING },
      { id: 4, name: "Las", program: EXPLORING },
    ],
    nextProgramId: 5,
  };
}

/** The same map run ended in death with a streak of 7, as an ended map run holds one. */
function died(state) {
  return { ...state, run: { ...state.run, death: DEATH, streak: 7 } };
}

function deepFreeze(value) {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const inner of Object.values(value)) deepFreeze(inner);
  }
  return value;
}

/** A map run paused at its first discovery, the first chill, from a program holding the empty group. */
function pausedAtDiscovery() {
  const sent = send(
    createCharacter(newGame(), "Ala").state,
    { mapId: MAP_ID, characterId: 1, programId: 1 },
    REAL_MS,
  ).state;
  return advanceMinutes(sent, 100).state;
}

test("„Zapisz w programie” after an edit of the copy gives the program the copy's content and leaves the streak", () => {
  const before = editedAndRunning();
  assert.equal(before.run.streak, 10, "precondition: a streak of 10");
  assert.deepEqual(before.programs[0].program, EXPLORING);
  const { state, events } = saveCopyIntoProgram(before);
  assert.deepEqual(state.programs[0].program, EXPLORING_THEN_WANDERING);
  assert.deepEqual(state.run.copy.base, EXPLORING_THEN_WANDERING);
  assert.deepEqual(state.run.copy.program, EXPLORING_THEN_WANDERING);
  assert.equal(state.run.streak, 10);
  assert.deepEqual(events, []);
});

test("a copy just taken has no unsaved changes and its program no changes the copy lacks; without a map run both are false", () => {
  const sent = sentWith(EXPLORING);
  assert.equal(copyHasUnsavedChanges(sent), false);
  assert.equal(programHasChangesCopyLacks(sent), false);
  assert.equal(copyHasUnsavedChanges(newGame()), false);
  assert.equal(programHasChangesCopyLacks(newGame()), false);
});

test("an edit of the copy makes it unsaved, and an edit put back makes it equal again", () => {
  const edited = setProgram(sentWith(EXPLORING), EXPLORING_THEN_WANDERING);
  assert.equal(copyHasUnsavedChanges(edited.state), true);
  assert.equal(programHasChangesCopyLacks(edited.state), false);
  const back = setProgram(edited.state, EXPLORING).state;
  assert.equal(copyHasUnsavedChanges(back), false);
});

test("a rule added and then deleted still counts as an unsaved change, the identity counter having moved", () => {
  const added = setProgram(sentWith(EXPLORING), EXPLORING_THEN_WANDERING);
  const deleted = setProgram(added.state, { ...EXPLORING, nextRuleId: 3 });
  assert.deepEqual(deleted.state.run.copy.program.groups, EXPLORING.groups);
  assert.equal(copyHasUnsavedChanges(deleted.state), true);
});

test("an edit of the program the copy came from makes the program hold changes the copy lacks, and an edit put back does not", () => {
  const sent = withOthers(sentWith(EXPLORING));
  const edited = editProgram(sent, 1, WANDERING).state;
  assert.equal(programHasChangesCopyLacks(edited), true);
  assert.equal(copyHasUnsavedChanges(edited), false);
  const back = editProgram(edited, 1, EXPLORING).state;
  assert.equal(programHasChangesCopyLacks(back), false);
  const other = editProgram(sent, 3, EXPLORING_THEN_WANDERING).state;
  assert.equal(programHasChangesCopyLacks(other), false);
});

test("a copy whose program is deleted has unsaved changes and its program no changes the copy lacks", () => {
  const sent = send(
    withOthers(ready(EXPLORING)),
    { mapId: MAP_ID, characterId: 1, programId: 3 },
    REAL_MS,
  ).state;
  const gone = deleteProgram(sent, 3).state;
  assert.equal(gone.run.copy.programId, null);
  assert.equal(copyHasUnsavedChanges(gone), true);
  assert.equal(programHasChangesCopyLacks(gone), false);
});

test("„Zapisz w programie” leaves the copy, the streak, the beaten attacks and the counts, and the other programs", () => {
  const before = withOthers(editedAndRunning());
  assert.deepEqual(before.ruleCounts, { 1: 1, 2: 0 }, "precondition: counts");
  const { state } = saveCopyIntoProgram(before);
  assert.equal(state.run.streak, before.run.streak);
  assert.equal(state.run.defeatedAttacks, before.run.defeatedAttacks);
  assert.deepEqual(state.ruleCounts, { 1: 1, 2: 0 });
  assert.deepEqual(state.run.copy.program, before.run.copy.program);
  assert.equal(state.run.copy.programId, 1);
  assert.deepEqual(state.programs.slice(1), before.programs.slice(1));
  assert.equal(copyHasUnsavedChanges(state), false);
  assert.equal(programHasChangesCopyLacks(state), false);
});

test("„Zapisz w programie” replaces changes the copy lacks at once, without a confirmation", () => {
  const before = editProgram(editedAndRunning(), 1, WANDERING).state;
  assert.equal(programHasChangesCopyLacks(before), true);
  const { state } = saveCopyIntoProgram(before);
  assert.deepEqual(state.programs[0].program, EXPLORING_THEN_WANDERING);
  assert.equal(programHasChangesCopyLacks(state), false);
});

test("„Zapisz w programie” is allowed after death and keeps the streak of the ended map run", () => {
  const { state } = saveCopyIntoProgram(died(editedAndRunning()));
  assert.deepEqual(state.programs[0].program, EXPLORING_THEN_WANDERING);
  assert.equal(state.run.streak, 7);
});

test("„Zapisz w programie” is refused without a map run, without unsaved changes and with the program gone", () => {
  assert.throws(() => saveCopyIntoProgram(newGame()), /no map run/);
  assert.throws(
    () => saveCopyIntoProgram(sentWith(EXPLORING)),
    /no unsaved changes/,
  );
  const edited = setProgram(
    withOthers(sentWith(EXPLORING)),
    EXPLORING_THEN_WANDERING,
  ).state;
  const gone = deleteProgram(edited, 1).state;
  assert.equal(gone.run.copy.programId, null);
  assert.throws(() => saveCopyIntoProgram(gone), /gone/);
});

test("„Zapisz jako nowy program” adds the copy's content at the end of the list under the next number, and the copy belongs to it", () => {
  const before = withOthers(editedAndRunning());
  const { state } = saveCopyAsNewProgram(before, "  Nocna  ");
  assert.deepEqual(state.programs.at(-1), {
    id: 5,
    name: "Nocna",
    program: EXPLORING_THEN_WANDERING,
  });
  assert.deepEqual(
    state.programs.slice(0, 3).map(({ id }) => id),
    [1, 3, 4],
  );
  assert.deepEqual(state.programs[0], before.programs[0]);
  assert.equal(state.nextProgramId, 6);
  assert.equal(state.run.copy.programId, 5);
  assert.equal(state.run.copy.deletedName, null);
  assert.deepEqual(state.run.copy.program, EXPLORING_THEN_WANDERING);
  assert.deepEqual(state.run.copy.base, EXPLORING_THEN_WANDERING);
  assert.equal(copyHasUnsavedChanges(state), false);
  assert.equal(state.lastUsedPrograms[1], 5);
});

test("„Zapisz jako nowy program” is no switch: the streak, the beaten attacks, the counts and the entered-with program stay", () => {
  const before = withOthers(editedAndRunning());
  assert.equal(before.run.streak, 10, "precondition: a streak of 10");
  const { state } = saveCopyAsNewProgram(before, "Nocna");
  assert.equal(state.run.streak, 10);
  assert.equal(state.run.defeatedAttacks, before.run.defeatedAttacks);
  assert.deepEqual(state.ruleCounts, { 1: 1, 2: 0 });
  assert.equal(state.lastEnteredProgram, before.lastEnteredProgram);
});

test("„Zapisz jako nowy program” works where the program is gone and after death", () => {
  const gone = deleteProgram(withOthers(editedAndRunning()), 1).state;
  assert.equal(gone.run.copy.deletedName, "Program");
  const saved = saveCopyAsNewProgram(gone, "Nowa").state;
  assert.equal(saved.run.copy.programId, 5);
  assert.equal(saved.run.copy.deletedName, null);
  const ended = saveCopyAsNewProgram(died(editedAndRunning()), "Nowa").state;
  assert.equal(ended.run.streak, 7);
  assert.equal(ended.programs.length, 2);
});

test("„Zapisz jako nowy program” is refused without a map run, without unsaved changes and on a name that is empty or taken", () => {
  assert.throws(() => saveCopyAsNewProgram(newGame(), "Nowa"), /no map run/);
  assert.throws(
    () => saveCopyAsNewProgram(sentWith(EXPLORING), "Nowa"),
    /no unsaved changes/,
  );
  const edited = setProgram(sentWith(EXPLORING), EXPLORING_THEN_WANDERING);
  assert.throws(() => saveCopyAsNewProgram(edited.state, "   "), /empty/);
  assert.throws(() => saveCopyAsNewProgram(edited.state, " PROGRAM "), /taken/);
});

test("„Porzuć zmiany” returns the copy to its base, reconciles the counts and zeroes the streak and the beaten attacks", () => {
  const before = editedAndRunning();
  assert.equal(before.run.streak, 10, "precondition: a streak of 10");
  const { state } = discardCopyChanges(before);
  assert.deepEqual(state.run.copy.program, EXPLORING);
  assert.deepEqual(state.run.copy.base, EXPLORING);
  assert.deepEqual(state.ruleCounts, { 1: 1 });
  assert.equal(state.run.streak, 0);
  assert.equal(state.run.defeatedAttacks, 0);
  assert.equal(copyHasUnsavedChanges(state), false);
  assert.deepEqual(state.programs, before.programs);
});

test("„Porzuć zmiany” starts again the count of a rule whose content the discard changes", () => {
  const wandering = setProgram(sentWith(EXPLORING), WANDERING).state;
  // The exploring in progress lasts 20 game minutes; after it the copy's rule wanders and fires.
  const running = advanceMinutes(wandering, 30).state;
  assert.ok(running.ruleCounts[1] > 0, "precondition: the rule has fired");
  const { state } = discardCopyChanges(running);
  assert.deepEqual(state.run.copy.program, EXPLORING);
  assert.deepEqual(state.ruleCounts, { 1: 0 });
});

test("„Porzuć zmiany” after death leaves the streak of the ended map run", () => {
  const { state } = discardCopyChanges(died(editedAndRunning()));
  assert.deepEqual(state.run.copy.program, EXPLORING);
  assert.equal(state.run.streak, 7);
  assert.deepEqual(state.ruleCounts, { 1: 1 });
});

test("„Porzuć zmiany” is refused without a map run, without unsaved changes and with the program gone", () => {
  assert.throws(() => discardCopyChanges(newGame()), /no map run/);
  assert.throws(
    () => discardCopyChanges(sentWith(EXPLORING)),
    /no unsaved changes/,
  );
  const edited = setProgram(
    withOthers(sentWith(EXPLORING)),
    EXPLORING_THEN_WANDERING,
  ).state;
  assert.throws(
    () => discardCopyChanges(deleteProgram(edited, 1).state),
    /gone/,
  );
});

test("a switch gives the map run a fresh copy of the other program, with the streak, the beaten attacks and the counts at zero", () => {
  const before = withOthers(editedAndRunning());
  assert.equal(before.run.streak, 10, "precondition: a streak of 10");
  const { state, events } = switchProgram(before, 3);
  assert.deepEqual(state.run.copy, {
    program: WANDERING,
    programId: 3,
    deletedName: null,
    base: WANDERING,
  });
  assert.equal(state.run.streak, 0);
  assert.equal(state.run.defeatedAttacks, 0);
  assert.deepEqual(state.ruleCounts, { 1: 0 });
  assert.equal(state.lastUsedPrograms[1], 3);
  assert.deepEqual(events, []);
});

test("a switch to a program of the same rules zeroes the streak as well", () => {
  const running = advanceMinutes(withOthers(sentWith(EXPLORING)), 10).state;
  assert.equal(running.run.streak, 10, "precondition: a streak of 10");
  const { state } = switchProgram(running, 4);
  assert.equal(state.run.streak, 0);
  assert.equal(state.run.copy.programId, 4);
});

test("a switch leaves the seed, the minute, the map, the body, the backpack and the action in progress, and the state around the map run", () => {
  const before = withOthers(editedAndRunning());
  const { state } = switchProgram(before, 3);
  const apart = (run) => ({
    ...run,
    copy: null,
    streak: null,
    defeatedAttacks: null,
  });
  assert.deepEqual(apart(state.run), apart(before.run));
  const around = (game) => ({
    ...game,
    run: null,
    ruleCounts: null,
    lastUsedPrograms: null,
  });
  assert.deepEqual(around(state), around(before));
});

test("a switch leaves the pause as it stands, a pause at a discovery included", () => {
  const found = withOthers(pausedAtDiscovery());
  assert.equal(found.paused, true, "precondition: paused at a discovery");
  assert.notEqual(found.discovery, null, "precondition: a discovery held");
  const switched = switchProgram(found, 3).state;
  assert.equal(switched.paused, true);
  assert.deepEqual(switched.discovery, found.discovery);
  const running = withOthers(editedAndRunning());
  assert.equal(switchProgram(running, 3).state.paused, false);
  const paused = setPaused(running, true).state;
  assert.equal(switchProgram(paused, 3).state.paused, true);
});

test("a switch is refused without a map run, after death, for a program not on the list and for the program of the copy", () => {
  const running = withOthers(editedAndRunning());
  assert.throws(() => switchProgram(newGame(), 1), /no map run/);
  assert.throws(() => switchProgram(died(running), 3), /ended/);
  assert.throws(() => switchProgram(running, 2), /no program 2/);
  assert.throws(() => switchProgram(running, 1), /already belongs/);
});

test("a switch is allowed where the copy's program is gone, to any program of the list", () => {
  const gone = deleteProgram(withOthers(editedAndRunning()), 1).state;
  const { state } = switchProgram(gone, 4);
  assert.equal(state.run.copy.programId, 4);
  assert.equal(state.run.copy.deletedName, null);
});

test("the rule the first chill writes is neither an unsaved change nor a change the save announces", () => {
  const found = pausedAtDiscovery();
  assert.deepEqual(found.programs[0].program.groups[0].rules, [
    { id: 1, condition: ALWAYS, action: { kind: "explore" } },
  ]);
  assert.deepEqual(found.run.copy.program, found.programs[0].program);
  assert.deepEqual(found.run.copy.base, found.programs[0].program);
  assert.equal(copyHasUnsavedChanges(found), false);
  assert.equal(programHasChangesCopyLacks(found), false);
});

test("no operation changes the state it is given", () => {
  const edited = deepFreeze(withOthers(editedAndRunning()));
  const ended = deepFreeze(died(withOthers(editedAndRunning())));
  assert.doesNotThrow(() => saveCopyIntoProgram(edited));
  assert.doesNotThrow(() => saveCopyAsNewProgram(edited, "Nocna"));
  assert.doesNotThrow(() => discardCopyChanges(edited));
  assert.doesNotThrow(() => switchProgram(edited, 3));
  assert.doesNotThrow(() => saveCopyIntoProgram(ended));
  assert.doesNotThrow(() => copyHasUnsavedChanges(edited));
  assert.doesNotThrow(() => programHasChangesCopyLacks(edited));
});

tests/sim/copy.test.mjs.source:
// The copy a manual map run carries out and the player's programs in the game state. Expectations
// come from the task "programy-gracza", the vault file `programy_gracza_loop2.md` (D-82), its To do
// 1, 5, 6, 7, 10 and 11, and from D-93, D-123, D-164, D-165 and D-170 in foundations/decisions.md.
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  advanceMinutes,
  createCharacter,
  end,
  newGame,
  restart,
  send,
  setProgram,
} from "../../dist/public/sim/game.js";
import { programFromRules } from "./program-fixture.mjs";
import { newKnowingGame } from "./understanding-fixture.mjs";

const MAP_ID = Object.keys(MAPS)[0];
const REAL_MS = 1760000000000;
const ALWAYS = { kind: "always" };
const rule = (condition, action) => ({ condition, action });
const EXPLORE_ALWAYS = rule(ALWAYS, { kind: "explore" });
const EXPLORING = programFromRules(rule(ALWAYS, { kind: "explore" }));
const WANDER_FIRST = programFromRules(
  rule(ALWAYS, { kind: "wander" }),
  rule(ALWAYS, { kind: "explore" }),
);
// The program of a new game and of „Nowy program”: the empty rule group „Program” under „Zawsze”
// (D-91; To do 1).
const EMPTY = {
  groups: [{ id: 1, name: "Program", condition: ALWAYS, rules: [] }],
  tripPlan: { take: [], bring: [] },
  nextGroupId: 2,
  nextRuleId: 1,
};

/** A knowing game whose program 1 holds `program`, with Ala, character 1, sent to the first map. */
function sent(program = EXPLORING) {
  const ready = createCharacter(
    setProgram(newKnowingGame(), program).state,
    "Ala",
  ).state;
  return send(ready, { mapId: MAP_ID, characterId: 1 }, REAL_MS).state;
}

/**
 * A game of Ala, character 1, and Bartek, character 2, holding the programs 1 and 3 — program 2
 * stands for one deleted — and the records `records`.
 */
function twoPrograms(records = {}, game = newKnowingGame()) {
  const team = createCharacter(createCharacter(game, "Ala").state, "Bartek");
  return {
    ...team.state,
    programs: [
      { id: 1, name: "Program", program: EXPLORING },
      { id: 3, name: "Las", program: WANDER_FIRST },
    ],
    nextProgramId: 4,
    ...records,
  };
}

test("a new game holds program 1, „Program”, with the empty rule group „Program” under „Zawsze”, the next program number 2 and no record of a program", () => {
  const state = newGame();
  assert.deepEqual(state.programs, [
    { id: 1, name: "Program", program: EMPTY },
  ]);
  assert.equal(state.nextProgramId, 2);
  assert.deepEqual(state.pickedPrograms, {});
  assert.deepEqual(state.lastUsedPrograms, {});
  assert.equal(state.lastEnteredProgram, null);
  assert.equal(state.countsProgram, null);
});

// To do 7: an edit during a map run goes into the copy; the program it was taken from stays.
test("an edit during a map run leaves program 1 as it was while the map run carries out the edited copy", () => {
  // Exploration lasts 20 minutes from minute 0, so the next rule is picked at minute 20.
  let state = advanceMinutes(sent(), 5).state;
  state = setProgram(state, WANDER_FIRST).state;
  assert.deepEqual(state.programs[0].program, EXPLORING);
  assert.deepEqual(state.run.copy, {
    program: WANDER_FIRST,
    programId: 1,
    deletedName: null,
    base: EXPLORING,
  });
  const at20 = advanceMinutes(state, 15).state;
  assert.equal(at20.run.minute, 20);
  assert.deepEqual(at20.run.current.activity.action, { kind: "wander" });
  assert.deepEqual(at20.programs[0].program, EXPLORING);
  const ended = end(at20).state;
  assert.deepEqual(ended.programs[0].program, EXPLORING);
});

// D-164, D-170: a send takes a copy of the program passed and records it for the character.
test("a send with a program number carries out a copy of that program, whose base is its content, makes it the character's program used last and the one entered with last, and clears the character's pick", () => {
  const state = twoPrograms({ pickedPrograms: { 1: 1, 2: 1 } });
  const { run, ...records } = send(
    state,
    { mapId: MAP_ID, characterId: 1, programId: 3 },
    REAL_MS,
  ).state;
  assert.deepEqual(run.copy, {
    program: WANDER_FIRST,
    programId: 3,
    deletedName: null,
    base: WANDER_FIRST,
  });
  assert.deepEqual(run.current.activity.action, { kind: "wander" });
  assert.deepEqual(records.pickedPrograms, { 2: 1 });
  assert.deepEqual(records.lastUsedPrograms, { 1: 3 });
  assert.equal(records.lastEnteredProgram, 3);
  assert.deepEqual(records.programs, state.programs);
  assert.deepEqual(records.ruleCounts, { 1: 1, 2: 0 });
});

test("a send refuses a program number not on the list, a deleted program's included, and changes nothing", () => {
  const state = twoPrograms();
  const before = structuredClone(state);
  for (const programId of [2, 4, 0, null, "1"]) {
    assert.throws(
      () => send(state, { mapId: MAP_ID, characterId: 1, programId }, REAL_MS),
      Error,
      `program ${String(programId)}`,
    );
  }
  assert.deepEqual(state, before);
});

// D-170; To do 5: the program a headquarters row stands on, which a send without a number takes.
test("a send without a program number takes the first still on the list of the row's pick, the character's program used last, the program entered with last and the first program", () => {
  const variants = [
    ["no record", {}, 1],
    ["entered with last", { lastEnteredProgram: 3 }, 3],
    ["entered with last, deleted", { lastEnteredProgram: 2 }, 1],
    [
      "used last before entered with last",
      { lastUsedPrograms: { 1: 3 }, lastEnteredProgram: 1 },
      3,
    ],
    [
      "used last, deleted",
      { lastUsedPrograms: { 1: 2 }, lastEnteredProgram: 3 },
      3,
    ],
    [
      "another character's program used last",
      { lastUsedPrograms: { 2: 3 }, lastEnteredProgram: 1 },
      1,
    ],
    [
      "the pick before used last",
      { pickedPrograms: { 1: 1 }, lastUsedPrograms: { 1: 3 } },
      1,
    ],
    [
      "the pick, deleted",
      { pickedPrograms: { 1: 2 }, lastUsedPrograms: { 1: 3 } },
      3,
    ],
    ["another character's pick", { pickedPrograms: { 2: 3 } }, 1],
  ];
  for (const [label, records, expected] of variants) {
    const result = send(
      twoPrograms(records),
      { mapId: MAP_ID, characterId: 1 },
      REAL_MS,
    ).state;
    assert.equal(result.run.copy.programId, expected, label);
    assert.equal(result.lastEnteredProgram, expected, label);
  }
});

// To do 6: „Restart” goes on with the copy of the map run it replaces, unsaved changes included.
test("Restart carries on the copy of the map run it replaces, its unsaved change included, with every count from zero and the programs as they were", () => {
  const edited = setProgram(
    advanceMinutes(sent(), 5).state,
    WANDER_FIRST,
  ).state;
  const restarted = restart(edited).state;
  assert.deepEqual(restarted.run.copy, edited.run.copy);
  assert.equal(restarted.run.minute, 0);
  assert.deepEqual(restarted.run.current.activity.action, { kind: "wander" });
  // Rule 1, „Zawsze → Wędruj”, fires at minute 0; rule 2 has not fired.
  assert.deepEqual(restarted.ruleCounts, { 1: 1, 2: 0 });
  assert.deepEqual(restarted.programs, edited.programs);
});

// To do 10, D-93: after „Zakończ” the counts stand beside the copy's program.
test("Zakończ keeps a count beside a rule of the copy's program whose condition and action are the copy's, and 0 beside one whose content differs", () => {
  const explorer = programFromRules(
    rule(ALWAYS, { kind: "explore" }),
    rule(ALWAYS, { kind: "wander" }),
  );
  const edit = structuredClone(explorer);
  edit.groups[0].rules[1].action = { kind: "explore" };
  edit.groups[0].rules.push({ id: 3, ...rule(ALWAYS, { kind: "wander" }) });
  edit.nextRuleId = 4;
  const editedRun = setProgram(sent(explorer), edit).state;
  // A run's history is an explicit input to the reconciliation, not computed by the code under test.
  const state = { ...editedRun, ruleCounts: { 1: 4, 2: 2, 3: 5 } };
  const ended = end(state).state;
  assert.deepEqual(ended.ruleCounts, { 1: 4, 2: 0 });
  assert.equal(ended.countsProgram, 1);
  assert.deepEqual(ended.programs[0].program, explorer);
});

test("Zakończ clears the counts where the copy's program is gone", () => {
  const running = sent();
  for (const programId of [null, 2]) {
    const state = {
      ...running,
      ruleCounts: { 1: 4 },
      run: {
        ...running.run,
        copy: { ...running.run.copy, programId, deletedName: "Program" },
      },
    };
    const ended = end(state).state;
    assert.equal(ended.ruleCounts, null, `program ${String(programId)}`);
    assert.equal(ended.countsProgram, null, `program ${String(programId)}`);
  }
});

// To do 11, D-123: the rule of the first chill (minute 84, see tests/sim/discovery.test.mjs).
test("the first chill writes „Zawsze → Eksploruj” into the copy, its base and the copy's program, and into no other program", () => {
  const state = {
    ...twoPrograms({}, newGame()),
    programs: [
      { id: 1, name: "Program", program: EMPTY },
      { id: 3, name: "Las", program: EMPTY },
    ],
  };
  const running = send(
    state,
    { mapId: MAP_ID, characterId: 1, programId: 3 },
    REAL_MS,
  ).state;
  const chilled = advanceMinutes(running, 84).state;
  assert.equal(chilled.run.minute, 84);
  const written = {
    ...EMPTY,
    groups: [{ ...EMPTY.groups[0], rules: [{ id: 1, ...EXPLORE_ALWAYS }] }],
    nextRuleId: 2,
  };
  assert.deepEqual(chilled.run.copy, {
    program: written,
    programId: 3,
    deletedName: null,
    base: written,
  });
  assert.deepEqual(chilled.programs, [
    { id: 1, name: "Program", program: EMPTY },
    { id: 3, name: "Las", program: written },
  ]);
});

test("the first chill writes the rule into the copy and its base alone where the copy's program is gone", () => {
  const running = send(
    createCharacter(newGame(), "Ala").state,
    { mapId: MAP_ID, characterId: 1 },
    REAL_MS,
  ).state;
  const orphaned = {
    ...running,
    run: {
      ...running.run,
      copy: { ...running.run.copy, programId: 2, deletedName: "Stary" },
    },
  };
  const chilled = advanceMinutes(orphaned, 84).state;
  assert.deepEqual(chilled.run.copy.program.groups[0].rules, [
    { id: 1, ...EXPLORE_ALWAYS },
  ]);
  assert.deepEqual(chilled.run.copy.base, chilled.run.copy.program);
  assert.deepEqual(chilled.programs, orphaned.programs);
});

// Plan, Choices: outside a map run `setProgram` edits the program a character with no pick and no
// program used last goes with.
test("setProgram outside a map run edits the program entered with last, or else the first of the list, and reconciles counts only where they stand beside it", () => {
  const entered = twoPrograms({ lastEnteredProgram: 3 });
  const third = setProgram(entered, EXPLORING).state;
  assert.deepEqual(
    third.programs.map((saved) => saved.program),
    [EXPLORING, EXPLORING],
  );
  const gone = setProgram(
    twoPrograms({ lastEnteredProgram: 2 }),
    WANDER_FIRST,
  ).state;
  assert.deepEqual(
    gone.programs.map((saved) => saved.program),
    [WANDER_FIRST, WANDER_FIRST],
  );
  // Counts beside program 1 stay when program 3 is edited, and follow an edit of program 3.
  const besideFirst = { ...entered, ruleCounts: { 1: 4 }, countsProgram: 1 };
  assert.deepEqual(setProgram(besideFirst, EXPLORING).state.ruleCounts, {
    1: 4,
  });
  const besideThird = {
    ...entered,
    ruleCounts: { 1: 4, 2: 2 },
    countsProgram: 3,
  };
  // Program 3 „Zawsze → Wędruj”, „Zawsze → Eksploruj” becomes „Zawsze → Eksploruj” alone.
  assert.deepEqual(setProgram(besideThird, EXPLORING).state.ruleCounts, {
    1: 0,
  });
});

// D-119 and spec constraint D-90: the map run carries out the copy reduced to the character's
// repertoire; a rule outside it is passed over and stays in the copy.
test("a copy rule outside the character's repertoire is passed over and stays in the copy", () => {
  // A new game knows no action, so „Zawsze → Eksploruj” is outside the repertoire until the first
  // chill.
  const ready = createCharacter(setProgram(newGame(), EXPLORING).state, "Ala");
  const running = send(
    ready.state,
    { mapId: MAP_ID, characterId: 1 },
    REAL_MS,
  ).state;
  assert.deepEqual(running.run.current.activity, { kind: "wait" });
  assert.deepEqual(running.run.copy.program, EXPLORING);
});

