import assert from "node:assert/strict";
import { test } from "node:test";
import {
  hexCenter,
  hexCorners,
  hexDistance,
  nearestTile,
  neighbours,
  offsetToAxial,
  sameHex,
  tileAt,
  tileLabel,
} from "../../dist/public/sim/hex.js";

const SIZE = 24;
const WIDTH = Math.sqrt(3) * SIZE;

/** Row-major rectangle of tiles with one step cost; stock marks the tiles that qualify. */
function grid(width, height, stepMinutes = 5) {
  const tiles = [];
  for (let row = 0; row < height; row += 1) {
    for (let col = 0; col < width; col += 1) {
      tiles.push({
        col,
        row,
        at: offsetToAxial(col, row),
        revealed: false,
        stepMinutes,
        stock: {},
      });
    }
  }
  return tiles;
}
const is = (at) => (tile) => sameHex(tile.at, at);
const close = (a, b) => assert.ok(Math.abs(a - b) < 1e-9, `${a} != ${b}`);

test("offset coordinates convert to axial with odd rows shifted right", () => {
  assert.deepEqual(offsetToAxial(0, 0), { q: 0, r: 0 });
  assert.deepEqual(offsetToAxial(1, 1), { q: 1, r: 1 });
  assert.deepEqual(offsetToAxial(0, 2), { q: -1, r: 2 });
});

test("sameHex and tileAt compare axial coordinates", () => {
  const tiles = grid(3, 3);
  assert.equal(sameHex({ q: 1, r: 2 }, { q: 1, r: 2 }), true);
  assert.equal(sameHex({ q: 1, r: 2 }, { q: 2, r: 1 }), false);
  assert.equal(tileAt(tiles, offsetToAxial(2, 1)), tiles[5]);
  assert.equal(tileAt(tiles, { q: 9, r: 9 }), undefined);
});

test("a tile inside the grid has six neighbours, the corner (0,0) has two, in tile-list order", () => {
  const tiles = grid(4, 4);
  const inner = neighbours(tiles, offsetToAxial(1, 1));
  assert.equal(inner.length, 6);
  assert.deepEqual(
    inner.map((t) => [t.col, t.row]),
    [
      [1, 0],
      [2, 0],
      [0, 1],
      [2, 1],
      [1, 2],
      [2, 2],
    ],
  );
  const corner = neighbours(tiles, offsetToAxial(0, 0));
  assert.deepEqual(
    corner.map((t) => [t.col, t.row]),
    [
      [1, 0],
      [0, 1],
    ],
  );
});

test("hex distance counts steps", () => {
  assert.equal(hexDistance({ q: 0, r: 0 }, { q: 0, r: 0 }), 0);
  assert.equal(hexDistance({ q: 0, r: 0 }, { q: 1, r: 0 }), 1);
  assert.equal(hexDistance({ q: 0, r: 0 }, { q: 1, r: 1 }), 2);
  assert.equal(hexDistance(offsetToAxial(0, 0), offsetToAxial(3, 3)), 5);
});

test("centres: origin at zero, next in row one tile width right, next row 1.5 radii lower", () => {
  const origin = hexCenter({ q: 0, r: 0 }, SIZE);
  close(origin.x, 0);
  close(origin.y, 0);
  const right = hexCenter(offsetToAxial(1, 0), SIZE);
  close(right.x, WIDTH);
  close(right.y, 0);
  const below = hexCenter(offsetToAxial(0, 1), SIZE);
  close(below.x, WIDTH / 2);
  close(below.y, 1.5 * SIZE);
  const two = hexCenter(offsetToAxial(0, 2), SIZE);
  close(two.x, 0);
  close(two.y, 3 * SIZE);
});

test("six corners at the radius, the first straight above the centre, clockwise", () => {
  const corners = hexCorners(SIZE);
  assert.equal(corners.length, 6);
  for (const c of corners) close(Math.hypot(c.x, c.y), SIZE);
  close(corners[0].x, 0);
  close(corners[0].y, -SIZE);
  close(corners[1].x, SIZE * Math.cos(-Math.PI / 6));
  close(corners[1].y, SIZE * Math.sin(-Math.PI / 6));
});

test("tile label is (col, row) in offset coordinates", () => {
  assert.equal(tileLabel({ col: 2, row: 3 }), "(2, 3)");
});

test("nearestTile: the start tile qualifies at 0 minutes and is its own first step", () => {
  const tiles = grid(4, 1);
  const found = nearestTile(tiles, { q: 0, r: 0 }, () => true);
  assert.equal(found.tile, tiles[0]);
  assert.equal(found.minutes, 0);
  assert.deepEqual(found.next, { q: 0, r: 0 });
});

test("nearestTile: walks the shortest route and gives the first step", () => {
  const tiles = grid(4, 1);
  const found = nearestTile(tiles, { q: 0, r: 0 }, is({ q: 3, r: 0 }));
  assert.equal(found.minutes, 15);
  assert.deepEqual(found.next, { q: 1, r: 0 });
});

test("nearestTile: null when nothing qualifies", () => {
  assert.equal(
    nearestTile(grid(3, 3), { q: 0, r: 0 }, () => false),
    null,
  );
});

test("nearestTile: equally near tiles are decided by tile-list order", () => {
  const tiles = grid(4, 4);
  const from = offsetToAxial(1, 1);
  // (1,0) and (2,1) are both one step away; (1,0) comes first in the list.
  const found = nearestTile(
    tiles,
    from,
    (t) => (t.col === 1 && t.row === 0) || (t.col === 2 && t.row === 1),
  );
  assert.deepEqual([found.tile.col, found.tile.row], [1, 0]);
  assert.equal(found.minutes, 5);
});

test("nearestTile: the first step is the first neighbour in list order on a cheapest path", () => {
  const tiles = grid(4, 4);
  const from = offsetToAxial(0, 0);
  // (1,1) is two steps away via (1,0) or via (0,1): the earlier neighbour wins.
  const found = nearestTile(tiles, from, (t) => t.col === 1 && t.row === 1);
  assert.equal(found.minutes, 10);
  assert.deepEqual(found.next, offsetToAxial(1, 0));
});

test("nearestTile: a cheaper detour is preferred over a costly tile", () => {
  const tiles = grid(3, 2);
  tiles[1].stepMinutes = 20; // (1,0)
  const found = nearestTile(
    tiles,
    offsetToAxial(0, 0),
    is(offsetToAxial(2, 0)),
  );
  assert.equal(found.minutes, 15);
  assert.deepEqual(found.next, offsetToAxial(0, 1));
});

tests/sim/layout.test.mjs.source:
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import { offsetToAxial, sameHex } from "../../dist/public/sim/hex.js";
import { drawLayout } from "../../dist/public/sim/layout.js";
import {
  mixSeed,
  nextRandom,
  streamState,
} from "../../dist/public/sim/random.js";

const map = Object.values(MAPS)[0];
const resourceIds = map.resources.map((resource) => resource.id);

test("tiles are row-major, unrevealed, with the map step cost", () => {
  const { tiles } = drawLayout(map, 1);
  assert.equal(tiles.length, map.width * map.height);
  tiles.forEach((tile, index) => {
    assert.equal(tile.col, index % map.width);
    assert.equal(tile.row, Math.floor(index / map.width));
    assert.deepEqual(tile.at, offsetToAxial(tile.col, tile.row));
    assert.equal(tile.revealed, false);
    assert.equal(tile.stepMinutes, map.stepMinutes);
  });
});

test("only the map resources appear, each with its full stock", () => {
  for (let seed = 1; seed <= 20; seed += 1) {
    for (const tile of drawLayout(map, seed).tiles) {
      for (const [id, stock] of Object.entries(tile.stock)) {
        const def = map.resources.find((resource) => resource.id === id);
        assert.ok(def, `unknown resource ${id}`);
        assert.equal(stock, def.stock);
      }
    }
  }
});

test("the entrance is the fixed one and lies on the map", () => {
  for (const seed of [1, 2, 3]) {
    const { tiles, entrance } = drawLayout(map, seed);
    assert.deepEqual(
      entrance,
      offsetToAxial(map.entrance.col, map.entrance.row),
    );
    assert.ok(tiles.some((tile) => sameHex(tile.at, entrance)));
  }
});

test("Las — głębiej draws its entrance from every row-major tile after resources", () => {
  const deep = MAPS.forestDeep;
  const seedOne = drawLayout(deep, 1);
  assert.ok(
    resourceIds.every((id) => seedOne.tiles.some((tile) => id in tile.stock)),
    "precondition: seed 1 needs no resource-guarantee draws",
  );
  let drawState = streamState(1, "layout");
  for (
    let index = 0;
    index < deep.width * deep.height * deep.resources.length;
    index += 1
  ) {
    drawState = nextRandom(drawState).state;
  }
  const entranceDraw = nextRandom(drawState).value;
  const entranceIndex = Math.floor(entranceDraw * deep.width * deep.height);
  assert.deepEqual(
    seedOne.entrance,
    offsetToAxial(
      entranceIndex % deep.width,
      Math.floor(entranceIndex / deep.width),
    ),
    "entrance draw follows all row-major resource draws",
  );
  const entries = new Set();
  for (let seed = 1; seed <= 40; seed += 1) {
    const { tiles, entrance } = drawLayout(deep, seed);
    const entranceTile = tiles.find((tile) => sameHex(tile.at, entrance));
    assert.ok(entranceTile);
    entries.add(`${entranceTile.col},${entranceTile.row}`);
  }
  assert.ok(entries.size > 1, "the entrance does not stay fixed across seeds");
});

test("the same seed gives the same tiles, another seed other tiles", () => {
  assert.deepEqual(drawLayout(map, 7), drawLayout(map, 7));
  assert.notDeepEqual(drawLayout(map, 1).tiles, drawLayout(map, 2).tiles);
});

test("every resource with positive density lies on at least one tile, seeds 1-20", () => {
  for (let seed = 1; seed <= 20; seed += 1) {
    const { tiles } = drawLayout(map, seed);
    for (const id of resourceIds) {
      assert.ok(
        tiles.some((tile) => id in tile.stock),
        `seed ${seed}: ${id} missing`,
      );
    }
  }
});

test("the minimum guarantee places a resource nobody drew", () => {
  const rare = {
    ...map,
    resources: map.resources.map((resource) => ({
      ...resource,
      density: 0.0001,
    })),
  };
  for (let seed = 1; seed <= 20; seed += 1) {
    const { tiles } = drawLayout(rare, seed);
    for (const id of resourceIds) {
      assert.ok(
        tiles.some((tile) => id in tile.stock),
        `seed ${seed}: ${id} missing`,
      );
    }
  }
});

test("a resource of zero density is never placed", () => {
  const none = {
    ...map,
    resources: map.resources.map((resource) => ({ ...resource, density: 0 })),
  };
  assert.ok(
    drawLayout(none, 3).tiles.every(
      (tile) => Object.keys(tile.stock).length === 0,
    ),
  );
});

test("drawLayout does not change the map", () => {
  const before = JSON.stringify(map);
  drawLayout(map, 4);
  assert.equal(JSON.stringify(map), before);
});

// Fixed expected values (D-22: the generator, the seed mixing and the draw order are a contract).
// Written out once from the code; a change to any of the three fails here.
test("golden values: the layout stream of seed 1, mixSeed(1, 1000) and the stocks of Las for seed 1", () => {
  let state = streamState(1, "layout");
  const values = [];
  for (let i = 0; i < 3; i += 1) {
    const step = nextRandom(state);
    values.push(step.value);
    state = step.state;
  }
  assert.deepEqual(
    values,
    [0.044911144534125924, 0.7811651250813156, 0.3564910045824945],
  );

  assert.equal(mixSeed(1, 1000), 2244977679);

  const stick = { stick: 12 };
  const berry = { berry: 8 };
  const moss = { moss: 6 };
  const fiber = { fiber: 6 };
  assert.deepEqual(
    drawLayout(MAPS.forest, 1).tiles.map((tile) => tile.stock),
    [
      { ...stick, ...moss },
      { ...stick, ...berry, ...fiber },
      {},
      { ...stick, ...berry },
      { ...berry },
      { ...stick },
      { ...stick, ...berry, ...moss },
      { ...stick },
      { ...stick, ...berry, ...fiber },
      { ...stick, ...fiber },
      { ...stick, ...berry, ...moss },
      { ...stick },
      { ...stick, ...fiber },
      { ...stick, ...berry, ...moss },
      { ...stick },
      { ...stick, ...moss },
    ],
  );
});

tests/sim/program-counts.test.mjs.source:
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  advanceMinutes,
  createCharacter,
  end,
  newGame,
  passRealTime,
  restart,
  send,
  setPaused,
  setProgram,
} from "../../dist/public/sim/game.js";
import { newKnowingGame } from "./understanding-fixture.mjs";

// D-92 and D-93 (foundations/decisions.md:1619,1641): starts, not elapsed minutes,
// with independent counts attached to stable identities. Deliberately no program fixture builder.
const PROGRAM = {
  groups: [
    {
      id: 8,
      name: "Explore",
      condition: { kind: "always" },
      rules: [
        { id: 17, condition: { kind: "always" }, action: { kind: "explore" } },
      ],
    },
    {
      id: 3,
      name: "Move",
      condition: { kind: "always" },
      rules: [
        { id: 91, condition: { kind: "always" }, action: { kind: "wander" } },
      ],
    },
  ],
  tripPlan: { take: [], bring: [] },
  nextGroupId: 9,
  nextRuleId: 92,
};
const SENT = { mapId: Object.keys(MAPS)[0], characterId: 1 };

function ready(program = PROGRAM) {
  return createCharacter(setProgram(newKnowingGame(), program).state, "Ala")
    .state;
}

function sent(program = PROGRAM) {
  return send(ready(program), SENT, 1760000000000).state;
}

test("counts stay absent through program edits before the first send", () => {
  assert.equal(newGame().ruleCounts, null);
  assert.equal(ready().ruleCounts, null);
  assert.equal(setProgram(ready(), PROGRAM).state.ruleCounts, null);
});

test("minute zero counts once; a multi-minute action, its finish and later waits add nothing", () => {
  const program = structuredClone(PROGRAM);
  program.groups[1].condition = { kind: "satietyBelow", value: 0 };
  const start = sent(program);
  assert.deepEqual(start.ruleCounts, { 17: 1, 91: 0 });
  const before = structuredClone(start);
  const during = advanceMinutes(start, 19).state;
  assert.deepEqual(during.ruleCounts, { 17: 1, 91: 0 });
  const finished = advanceMinutes(during, 1);
  assert.equal(finished.state.run.current.activity.kind, "wait");
  assert.ok(finished.events.some((event) => event.kind === "activityFinished"));
  assert.deepEqual(finished.state.ruleCounts, { 17: 1, 91: 0 });
  assert.deepEqual(advanceMinutes(finished.state, 3).state.ruleCounts, {
    17: 1,
    91: 0,
  });
  assert.deepEqual(start, before, "counting must not mutate the input state");
});

test("an initial wait leaves every rule at zero", () => {
  const program = structuredClone(PROGRAM);
  for (const group of program.groups)
    group.condition = { kind: "satietyBelow", value: 0 };
  const start = sent(program);
  assert.equal(
    start.run.current.activity.kind,
    "wait",
    "precondition: no eligible group",
  );
  assert.deepEqual(start.ruleCounts, { 17: 0, 91: 0 });
  assert.deepEqual(advanceMinutes(start, 3).state.ruleCounts, { 17: 0, 91: 0 });
});

test("later starts count and each restart or new send resets before the minute-zero choice", () => {
  const later = advanceMinutes(sent(), 20).state;
  assert.deepEqual(later.ruleCounts, { 17: 1, 91: 1 });
  assert.deepEqual(restart(later).state.ruleCounts, { 17: 1, 91: 0 });
  const stopped = end(later).state;
  assert.deepEqual(stopped.ruleCounts, { 17: 1, 91: 1 });
  assert.deepEqual(send(stopped, SENT, 1760000123456).state.ruleCounts, {
    17: 1,
    91: 0,
  });
});

test("pause and death retain counts, including an action interrupted by death", () => {
  const start = sent();
  const paused = setPaused(start, true).state;
  assert.deepEqual(passRealTime(paused, 60000).state.ruleCounts, {
    17: 1,
    91: 0,
  });
  const dying = {
    ...start,
    run: { ...start.run, body: { temperature: 30, satiety: 0, health: 0.01 } },
  };
  const died = advanceMinutes(dying, 1);
  assert.ok(
    died.state.run.death,
    "precondition: dies before exploration finishes",
  );
  assert.equal(
    died.events.some((event) => event.kind === "activityFinished"),
    false,
  );
  assert.deepEqual(died.state.ruleCounts, { 17: 1, 91: 0 });
  assert.deepEqual(passRealTime(died.state, 60000).state.ruleCounts, {
    17: 1,
    91: 0,
  });
  assert.deepEqual(end(died.state).state.ruleCounts, { 17: 1, 91: 0 });
  assert.deepEqual(restart(died.state).state.ruleCounts, { 17: 1, 91: 0 });
});

test("identical rules count independently and keep their counts after group reorder and transfer", () => {
  const program = structuredClone(PROGRAM);
  program.groups[1].rules[0].action = { kind: "explore" };
  const start = sent(program);
  assert.deepEqual(start.ruleCounts, { 17: 1, 91: 0 });
  const reordered = { ...program, groups: [...program.groups].reverse() };
  const moved = setProgram(start, reordered).state;
  assert.deepEqual(moved.ruleCounts, { 17: 1, 91: 0 });
  assert.deepEqual(restart(moved).state.ruleCounts, { 17: 0, 91: 1 });
  const transferred = structuredClone(program);
  transferred.groups[0].rules = [];
  transferred.groups[1].rules.push(program.groups[0].rules[0]);
  transferred.groups[1].name = "Renamed";
  transferred.groups[1].condition = { kind: "satietyBelow", value: 50 };
  assert.deepEqual(setProgram(start, transferred).state.ruleCounts, {
    17: 1,
    91: 0,
  });
  const withinGroup = structuredClone(transferred);
  withinGroup.groups[1].rules.reverse();
  assert.deepEqual(
    setProgram(setProgram(start, transferred).state, withinGroup).state
      .ruleCounts,
    { 17: 1, 91: 0 },
  );
});

test("every condition/action content field resets only its edited rule, also after Stop", () => {
  const variants = [
    [
      "condition kind",
      { kind: "always" },
      { kind: "explore" },
      { kind: "awayFromCampfire" },
      { kind: "explore" },
    ],
    [
      "condition resource",
      { kind: "hereBelow", resource: "stick", value: 2 },
      { kind: "explore" },
      { kind: "hereBelow", resource: "berry", value: 2 },
      { kind: "explore" },
    ],
    [
      "condition item",
      { kind: "itemBelow", item: "stick", value: 2 },
      { kind: "explore" },
      { kind: "itemBelow", item: "berry", value: 2 },
      { kind: "explore" },
    ],
    [
      "condition number",
      { kind: "temperatureBelow", value: 36.5 },
      { kind: "explore" },
      { kind: "temperatureBelow", value: 36.6 },
      { kind: "explore" },
    ],
    [
      "action kind",
      { kind: "always" },
      { kind: "explore" },
      { kind: "always" },
      { kind: "wander" },
    ],
    [
      "action resource",
      { kind: "always" },
      { kind: "gather", resource: "stick" },
      { kind: "always" },
      { kind: "gather", resource: "berry" },
    ],
  ];
  for (const [
    label,
    condition,
    action,
    nextCondition,
    nextAction,
  ] of variants) {
    const program = structuredClone(PROGRAM);
    program.groups[0].rules[0] = { id: 17, condition, action };
    // A completed history is an explicit input to reconciliation, not an expected result
    // calculated from the implementation under test.
    const state = { ...end(sent(program)).state, ruleCounts: { 17: 4, 91: 2 } };
    const before = structuredClone(state);
    const changed = structuredClone(program);
    changed.groups[0].rules[0] = {
      id: 17,
      condition: nextCondition,
      action: nextAction,
    };
    assert.deepEqual(
      setProgram(state, changed).state.ruleCounts,
      { 17: 0, 91: 2 },
      label,
    );
    assert.deepEqual(state, before, label);
  }
});

test("canonical equivalent content preserves history despite key order, extra fields and floating rounding", () => {
  const program = structuredClone(PROGRAM);
  program.groups[0].rules[0].condition = {
    kind: "temperatureBelow",
    value: 36.6,
  };
  const state = { ...end(sent(program)).state, ruleCounts: { 17: 4, 91: 2 } };
  const equivalent = structuredClone(program);
  equivalent.groups[0].rules[0] = {
    action: { unused: true, kind: "explore" },
    condition: { value: 36.60000000000001, kind: "temperatureBelow" },
    id: 17,
  };
  assert.deepEqual(setProgram(state, equivalent).state.ruleCounts, {
    17: 4,
    91: 2,
  });
  // Task "programy-gracza", To do 1: the program handed back is program 1 of the player's list.
  assert.deepEqual(
    setProgram(state, structuredClone(state.programs[0].program)).state
      .ruleCounts,
    { 17: 4, 91: 2 },
  );
});

test("deleting an active rule removes its count; adding its duplicate starts at zero and completion does not resurrect it", () => {
  const start = sent();
  const changed = structuredClone(PROGRAM);
  changed.groups[0].rules = [{ ...changed.groups[0].rules[0], id: 92 }];
  changed.nextRuleId = 93;
  const edited = setProgram(start, changed).state;
  assert.deepEqual(edited.ruleCounts, { 91: 0, 92: 0 });
  assert.equal(
    edited.run.current.activity.ruleId,
    17,
    "the already-started action is retained",
  );
  const finished = advanceMinutes(edited, 20).state;
  assert.deepEqual(finished.ruleCounts, { 91: 1, 92: 0 });
  assert.equal(
    finished.run.tiles.some((tile) => tile.revealed),
    true,
  );
});

test("editing an active rule resets it immediately and its old completion adds no count", () => {
  const start = sent();
  const changed = structuredClone(PROGRAM);
  changed.groups[0].rules[0].condition = { kind: "satietyBelow", value: 0 };
  const edited = setProgram(start, changed).state;
  assert.deepEqual(edited.ruleCounts, { 17: 0, 91: 0 });
  assert.deepEqual(advanceMinutes(edited, 20).state.ruleCounts, {
    17: 0,
    91: 1,
  });
});

test("batched, split and real-time minutes produce the same counts through later starts and death", () => {
  const start = sent();
  const batch = advanceMinutes(start, 1000).state;
  let split = start;
  for (let minute = 0; minute < 1000; minute += 1)
    split = advanceMinutes(split, 1).state;
  assert.ok(batch.run.death, "precondition: the span reaches death");
  assert.ok(
    batch.ruleCounts?.[17] > 1,
    "precondition: later exploration starts occurred",
  );
  assert.deepEqual(split.ruleCounts, batch.ruleCounts);
  assert.deepEqual(
    passRealTime(start, 1000000).state.ruleCounts,
    batch.ruleCounts,
  );
});

tests/sim/program-list.test.mjs.source:
// The operations on the player's program list. Expectations come from the task "programy-gracza",
// the vault file `programy_gracza_loop2.md` (To do 3, 4, 5 and 9), and from D-164, D-165, D-168,
// D-169 and D-170 in foundations/decisions.md. Every expected value is written out here.
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  advanceMinutes,
  createCharacter,
  end,
  newGame,
  send,
  setProgram,
} from "../../dist/public/sim/game.js";
import {
  createProgram,
  deleteProgram,
  editProgram,
  pickProgram,
  programName,
  renameProgram,
  suggestedProgramName,
} from "../../dist/public/sim/programs.js";
import { programFromRules } from "./program-fixture.mjs";
import { newKnowingGame } from "./understanding-fixture.mjs";

const MAP_ID = Object.keys(MAPS)[0];
const REAL_MS = 1760000000000;
const ALWAYS = { kind: "always" };
const rule = (condition, action) => ({ condition, action });
const EXPLORING = programFromRules(rule(ALWAYS, { kind: "explore" }));
const WANDERING = programFromRules(rule(ALWAYS, { kind: "wander" }));
const EMPTY = {
  groups: [{ id: 1, name: "Program", condition: ALWAYS, rules: [] }],
  tripPlan: { take: [], bring: [] },
  nextGroupId: 2,
  nextRuleId: 1,
};

const listed = (...names) =>
  names.map((name, index) => ({ id: index + 1, name, program: EMPTY }));

/** A knowing game with Ala (1) and Bartek (2) and the programs 1, 3 and 4 — 2 stands for a deleted one. */
function team(extra = {}) {
  const made = createCharacter(
    createCharacter(newKnowingGame(), "Ala").state,
    "Bartek",
  ).state;
  return {
    ...made,
    programs: [
      { id: 1, name: "Program", program: EXPLORING },
      { id: 3, name: "Las", program: WANDERING },
      { id: 4, name: "Noc", program: EMPTY },
    ],
    nextProgramId: 5,
    ...extra,
  };
}

function deepFreeze(value) {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const inner of Object.values(value)) deepFreeze(inner);
  }
  return value;
}

/** Ala, character 1, sent with program 3 of `team()`. */
function sentWithThird() {
  return send(team(), { mapId: MAP_ID, characterId: 1, programId: 3 }, REAL_MS)
    .state;
}

test("a second created program is named „Program 2” and takes the number 2", () => {
  const { state } = createProgram(newGame());
  assert.deepEqual(
    state.programs.map(({ id, name }) => [id, name]),
    [
      [1, "Program"],
      [2, "Program 2"],
    ],
  );
});

test("a created program holds the empty group „Program” under „Zawsze”, at the end, and takes the next number", () => {
  const { state, events } = createProgram(team());
  assert.deepEqual(state.programs.at(-1), {
    id: 5,
    name: "Program 2",
    program: EMPTY,
  });
  assert.deepEqual(
    state.programs.slice(0, 3).map(({ id }) => id),
    [1, 3, 4],
  );
  assert.equal(state.nextProgramId, 6);
  assert.deepEqual(events, []);
});

test("a number is not given again after a deletion", () => {
  const two = createProgram(newGame()).state;
  const again = createProgram(deleteProgram(two, 2).state).state;
  assert.deepEqual(
    again.programs.map(({ id, name }) => [id, name]),
    [
      [1, "Program"],
      [3, "Program 2"],
    ],
  );
});

test("the suggested name is „Program n” for the smallest n from 2 that no name takes, letter case ignored", () => {
  assert.equal(suggestedProgramName(listed("Program")), "Program 2");
  assert.equal(
    suggestedProgramName(listed("Program", "Program 2")),
    "Program 3",
  );
  assert.equal(
    suggestedProgramName(listed("Program", "Program 3")),
    "Program 2",
  );
  assert.equal(suggestedProgramName(listed("Program 1", "Las")), "Program 2");
  assert.equal(
    suggestedProgramName(listed("Program", "PROGRAM 2", "program 3")),
    "Program 4",
  );
});

test("a typed name is trimmed, and refused as empty or as taken regardless of letter case", () => {
  const programs = listed("Program", "Łąka");
  assert.deepEqual(programName(programs, "  Las \t"), {
    ok: true,
    name: "Las",
  });
  assert.deepEqual(programName(programs, ""), { ok: false, reason: "empty" });
  assert.deepEqual(programName(programs, " \t\n "), {
    ok: false,
    reason: "empty",
  });
  assert.deepEqual(programName(programs, " program "), {
    ok: false,
    reason: "taken",
  });
  assert.deepEqual(programName(programs, "ŁĄKA"), {
    ok: false,
    reason: "taken",
  });
  assert.deepEqual(programName(programs, "Program 2"), {
    ok: true,
    name: "Program 2",
  });
});

test("a program's own name in another letter case does not block its rename; the name has no length limit", () => {
  const programs = listed("Program", "Las");
  assert.deepEqual(programName(programs, "LAS", 2), { ok: true, name: "LAS" });
  assert.deepEqual(programName(programs, "LAS", 1), {
    ok: false,
    reason: "taken",
  });
  const long = "x".repeat(5000);
  assert.deepEqual(programName(programs, long), { ok: true, name: long });
});

test("a rename keeps the place, the number and the content, and stores the trimmed name", () => {
  const { state } = renameProgram(team(), 3, "  LAS  ");
  assert.deepEqual(
    state.programs.map(({ id, name }) => [id, name]),
    [
      [1, "Program"],
      [3, "LAS"],
      [4, "Noc"],
    ],
  );
  assert.deepEqual(state.programs[1].program, WANDERING);
});

test("a rename throws on an empty name, a taken name and a program not on the list", () => {
  assert.throws(() => renameProgram(team(), 3, "   "), /empty/);
  assert.throws(() => renameProgram(team(), 3, "noc"), /taken/);
  assert.throws(() => renameProgram(team(), 2, "Nowa"), /no program 2/);
});

test("a deletion removes the program, and is refused for the last one and for a program not on the list", () => {
  const { state } = deleteProgram(team(), 3);
  assert.deepEqual(
    state.programs.map(({ id }) => id),
    [1, 4],
  );
  assert.equal(state.nextProgramId, 5);
  assert.throws(() => deleteProgram(team(), 2), /no program 2/);
  assert.throws(() => deleteProgram(newGame(), 1), /last program/);
  const one = deleteProgram(deleteProgram(team(), 3).state, 4).state;
  assert.throws(() => deleteProgram(one, 1), /last program/);
});

test("deleting the copy's program leaves the copy on its content, its number none and its name kept", () => {
  const running = sentWithThird();
  const { state } = deleteProgram(running, 3);
  assert.equal(state.run.copy.programId, null);
  assert.equal(state.run.copy.deletedName, "Las");
  assert.deepEqual(state.run.copy.program, WANDERING);
  assert.deepEqual(state.run.copy.base, WANDERING);
  assert.deepEqual(
    { ...state.run, copy: null },
    { ...running.run, copy: null },
  );
});

test("deleting another program leaves the copy record as it is", () => {
  const running = sentWithThird();
  assert.deepEqual(deleteProgram(running, 4).state.run.copy, running.run.copy);
  assert.deepEqual(deleteProgram(running, 1).state.run.copy, running.run.copy);
});

test("deleting the program the counts stand beside clears the counts; deleting another leaves them", () => {
  const ended = {
    ...end(sentWithThird()).state,
    ruleCounts: { 1: 4 },
    countsProgram: 3,
  };
  const cleared = deleteProgram(ended, 3).state;
  assert.equal(cleared.ruleCounts, null);
  assert.equal(cleared.countsProgram, null);
  const kept = deleteProgram(ended, 4).state;
  assert.deepEqual(kept.ruleCounts, { 1: 4 });
  assert.equal(kept.countsProgram, 3);
});

test("a deletion during a map run leaves the counts of the copy", () => {
  const running = { ...sentWithThird(), ruleCounts: { 1: 4 } };
  const { state } = deleteProgram(running, 3);
  assert.deepEqual(state.ruleCounts, { 1: 4 });
  assert.equal(state.countsProgram, null);
});

test("Zakończ after the deletion of the copy's program clears the counts", () => {
  const running = advanceMinutes(sentWithThird(), 5).state;
  assert.notEqual(running.ruleCounts, null);
  const ended = end(deleteProgram(running, 3).state).state;
  assert.equal(ended.ruleCounts, null);
  assert.equal(ended.countsProgram, null);
  assert.equal(ended.run, null);
});

test("an edit replaces the content of the program numbered, the others stay", () => {
  const { state } = editProgram(team(), 3, EXPLORING);
  assert.deepEqual(state.programs[1], {
    id: 3,
    name: "Las",
    program: EXPLORING,
  });
  assert.deepEqual(state.programs[0].program, EXPLORING);
  assert.deepEqual(state.programs[2].program, EMPTY);
});

test("an edit is checked against the resources of the maps and throws on a program not on the list", () => {
  const gathering = programFromRules(
    rule(ALWAYS, { kind: "gather", resource: "stick" }),
  );
  assert.deepEqual(
    editProgram(team(), 4, gathering).state.programs[2].program,
    gathering,
  );
  const unknown = programFromRules(
    rule(ALWAYS, { kind: "gather", resource: "gold" }),
  );
  assert.throws(() => editProgram(team(), 4, unknown), /not a resource/);
  assert.throws(() => editProgram(team(), 2, EXPLORING), /no program 2/);
});

test("an edit reconciles the counts only where they stand beside the program edited", () => {
  const two = programFromRules(
    rule(ALWAYS, { kind: "explore" }),
    rule(ALWAYS, { kind: "wander" }),
  );
  const changed = structuredClone(two);
  changed.groups[0].rules[1].action = { kind: "explore" };
  const base = team({ ruleCounts: { 1: 4, 2: 2 }, countsProgram: 3 });
  const beside = {
    ...base,
    programs: [
      base.programs[0],
      { id: 3, name: "Las", program: two },
      base.programs[2],
    ],
  };
  assert.deepEqual(editProgram(beside, 3, changed).state.ruleCounts, {
    1: 4,
    2: 0,
  });
  assert.deepEqual(editProgram(beside, 4, EXPLORING).state.ruleCounts, {
    1: 4,
    2: 2,
  });
});

test("an edit of a saved program leaves the map run, its copy, its streak, its beaten attacks and its counts", () => {
  const running = advanceMinutes(sentWithThird(), 12).state;
  const counted = {
    ...running,
    ruleCounts: { 1: 7 },
    run: { ...running.run, streak: 9, defeatedAttacks: 2 },
  };
  for (const programId of [3, 1, 4]) {
    const { state } = editProgram(counted, programId, EXPLORING);
    assert.deepEqual(state.run, counted.run, `program ${String(programId)}`);
    assert.deepEqual(
      state.ruleCounts,
      { 1: 7 },
      `program ${String(programId)}`,
    );
  }
});

test("the list operations run in a map run and outside one alike", () => {
  for (const state of [team(), sentWithThird()]) {
    assert.equal(createProgram(state).state.programs.length, 4);
    assert.equal(
      renameProgram(state, 4, "Dzień").state.programs[2].name,
      "Dzień",
    );
    assert.equal(pickProgram(state, 2, 4).state.pickedPrograms[2], 4);
    assert.equal(deleteProgram(state, 4).state.programs.length, 2);
  }
});

test("the operations change nothing passed to them", () => {
  for (const state of [team(), sentWithThird()]) {
    const frozen = deepFreeze(structuredClone(state));
    createProgram(frozen);
    renameProgram(frozen, 3, "Inny");
    deleteProgram(frozen, 3);
    editProgram(frozen, 3, EXPLORING);
    pickProgram(frozen, 1, 4);
    assert.deepEqual(frozen, state);
  }
});

test("a pick names a character of the team and a program of the list", () => {
  const { state, events } = pickProgram(team(), 2, 3);
  assert.deepEqual(state.pickedPrograms, { 2: 3 });
  assert.deepEqual(events, []);
  assert.throws(() => pickProgram(team(), 3, 1), /no character 3/);
  assert.throws(() => pickProgram(team(), 1, 2), /no program 2/);
});

// The row's program (spec decision 4): the pick, the program used last, the program entered with
// last, the first of the list, each passed over once its program is deleted. It is read as the
// program a send without a number sends with.
const sentProgramOf = (state, characterId) =>
  send(state, { mapId: MAP_ID, characterId }, REAL_MS).state.run.copy.programId;

test("a row's program is the pick, then the program used last, then the one entered with last, then the first", () => {
  const records = {
    pickedPrograms: { 1: 4 },
    lastUsedPrograms: { 1: 3 },
    lastEnteredProgram: 3,
  };
  assert.equal(sentProgramOf(team(records), 1), 4);
  assert.equal(sentProgramOf(team({ ...records, pickedPrograms: {} }), 1), 3);
  assert.equal(
    sentProgramOf(
      team({ ...records, pickedPrograms: {}, lastUsedPrograms: {} }),
      1,
    ),
    3,
  );
  assert.equal(sentProgramOf(team(), 1), 1);
});

test("a row's program passes over each record once its program is deleted", () => {
  const all = team({
    pickedPrograms: { 1: 4 },
    lastUsedPrograms: { 1: 3 },
    lastEnteredProgram: 1,
  });
  assert.equal(sentProgramOf(deleteProgram(all, 4).state, 1), 3);
  assert.equal(
    sentProgramOf(deleteProgram(deleteProgram(all, 4).state, 3).state, 1),
    1,
  );
  const enteredGone = team({ lastEnteredProgram: 3 });
  assert.equal(sentProgramOf(deleteProgram(enteredGone, 3).state, 2), 1);
  const usedGone = team({
    lastEnteredProgram: 4,
    lastUsedPrograms: { 1: 3 },
  });
  assert.equal(sentProgramOf(deleteProgram(usedGone, 3).state, 1), 4);
});

test("a pick is kept through the creation of another character and cleared by the send", () => {
  const picked = pickProgram(team(), 1, 4).state;
  const another = createCharacter(picked, "Celina").state;
  assert.deepEqual(another.pickedPrograms, { 1: 4 });
  const sent = send(another, { mapId: MAP_ID, characterId: 1 }, REAL_MS).state;
  assert.equal(sent.run.copy.programId, 4);
  assert.deepEqual(sent.pickedPrograms, {});
  assert.equal(sent.lastUsedPrograms[1], 4);
  assert.equal(sent.lastEnteredProgram, 4);
});

test("a pick on one row leaves the other rows' programs", () => {
  const picked = pickProgram(team({ lastUsedPrograms: { 2: 3 } }), 1, 4).state;
  assert.equal(sentProgramOf(picked, 2), 3);
});

test("an edit of the copy reaches only the copy while the list holds more programs", () => {
  const { state } = setProgram(sentWithThird(), EXPLORING);
  assert.deepEqual(state.run.copy.program, EXPLORING);
  assert.deepEqual(state.programs[1].program, WANDERING);
});

tests/sim/program.test.mjs.source:
import {
  newGame,
  setProgram,
  createCharacter,
  send,
  advanceMinutes,
} from "../../dist/public/sim/game.js";
import { programFromRules } from "./program-fixture.mjs";
import assert from "node:assert/strict";
import { test } from "node:test";
import { BALANCE } from "../../dist/public/sim/data/balance.js";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import { sameHex } from "../../dist/public/sim/hex.js";
import {
  actionFeasible,
  chooseActivity,
  conditionHolds,
} from "../../dist/public/sim/program.js";
import { newMapRun } from "../../dist/public/sim/run.js";
import { newKnowingGame } from "./understanding-fixture.mjs";

const [mapId, map] = Object.entries(MAPS)[0];
// The id of a character of the team, which the map run carries.
const characterId = 1;
const [stick, berry] = map.resources.map((resource) => resource.id);

const ALWAYS = { kind: "always" };
const EXPLORE = { kind: "explore" };
const WANDER = { kind: "wander" };
const below = (resource, value) => ({ kind: "hereBelow", resource, value });
const walkTo = (resource) => ({ kind: "walkTo", resource });
const rule = (condition, action) => ({ condition, action });
const program = programFromRules;

/** A fresh map run of the first map at minute 0, its first activity chosen by `startProgram`. */
function freshRun(seed = 3, startProgram = program()) {
  return newMapRun(map, seed, startProgram, { mapId, characterId }).run;
}

/** The run with the character's tile replaced by `change(tile)`. */
function withHere(run, change) {
  return {
    ...run,
    tiles: run.tiles.map((tile) =>
      sameHex(tile.at, run.character.at) ? change({ ...tile }) : tile,
    ),
  };
}

/** The run with every tile revealed or not and without stock. */
function cleared(run, revealed) {
  return {
    ...run,
    tiles: run.tiles.map((tile) => ({ ...tile, revealed, stock: {} })),
  };
}

test("always holds", () => {
  assert.equal(conditionHolds(freshRun(), map, ALWAYS), true);
});

test("hereBelow reads 0 on an unrevealed tile, whatever lies there", () => {
  const run = withHere(freshRun(), (tile) => ({
    ...tile,
    revealed: false,
    stock: { [stick]: 12 },
  }));
  assert.equal(conditionHolds(run, map, below(stick, 1)), true);
});

test("hereBelow compares the true stock of a revealed tile", () => {
  const run = withHere(freshRun(), (tile) => ({
    ...tile,
    revealed: true,
    stock: { [stick]: 12 },
  }));
  assert.equal(conditionHolds(run, map, below(stick, 12)), false);
  assert.equal(conditionHolds(run, map, below(stick, 13)), true);
  assert.equal(
    conditionHolds(run, map, below(berry, 1)),
    true,
    "a lacking resource counts 0",
  );
});

test("hereBelow with N = 0 never holds", () => {
  const run = withHere(freshRun(), (tile) => ({
    ...tile,
    revealed: true,
    stock: {},
  }));
  assert.equal(conditionHolds(run, map, below(stick, 0)), false);
});

test("the first rule whose condition holds and whose action is feasible wins", () => {
  const run = freshRun();
  const chosen = chooseActivity(
    run,
    map,
    program(rule(ALWAYS, EXPLORE), rule(ALWAYS, WANDER)),
  );
  assert.deepEqual(chosen, { kind: "rule", ruleId: 1, action: EXPLORE });
});

test("a rule whose condition does not hold is skipped", () => {
  const run = freshRun();
  const chosen = chooseActivity(
    run,
    map,
    program(rule(below(stick, 0), WANDER), rule(ALWAYS, EXPLORE)),
  );
  assert.deepEqual(chosen, { kind: "rule", ruleId: 2, action: EXPLORE });
});

test("a rule whose action is not feasible is skipped", () => {
  const run = withHere(freshRun(), (tile) => ({ ...tile, revealed: true }));
  const chosen = chooseActivity(
    run,
    map,
    program(rule(ALWAYS, EXPLORE), rule(ALWAYS, WANDER)),
  );
  assert.deepEqual(chosen, { kind: "rule", ruleId: 2, action: WANDER });
});

test("with no applicable rule the character waits", () => {
  const run = cleared(freshRun(), true);
  assert.deepEqual(chooseActivity(run, map, program()), { kind: "wait" });
  assert.deepEqual(
    chooseActivity(
      run,
      map,
      program(rule(ALWAYS, EXPLORE), rule(ALWAYS, walkTo(stick))),
    ),
    {
      kind: "wait",
    },
  );
});

test("a wait lasts waitMinutes, one game minute", () => {
  assert.equal(BALANCE.waitMinutes, 1);
  const { run } = newMapRun(map, 3, program(), { mapId, characterId });
  assert.deepEqual(run.current, {
    activity: { kind: "wait" },
    startMinute: 0,
    endMinute: 1,
    stepTo: null,
  });
});

test("feasibility and choice do not draw from the wander generator", () => {
  const run = freshRun();
  const before = JSON.stringify(run);
  actionFeasible(run, map, WANDER);
  actionFeasible(run, map, WANDER);
  chooseActivity(run, map, program(rule(ALWAYS, WANDER)));
  chooseActivity(run, map, program(rule(ALWAYS, WANDER)));
  assert.equal(JSON.stringify(run), before);
});

test("the chosen action is a copy, not the program rule itself", () => {
  const rules = program(rule(ALWAYS, EXPLORE));
  const chosen = chooseActivity(freshRun(), map, rules);
  assert.notEqual(chosen.action, rules.groups[0].rules[0].action);
});

// D-23, D-90 and D-91: groups gate ordered rules; a new game gives a first empty group.
const group = (id, condition, rules) => ({
  id,
  name: `Group ${id}`,
  condition,
  rules,
});
const grouped = (...groups) => ({
  tripPlan: { take: [], bring: [] },
  nextGroupId: 100,
  nextRuleId: 1000,
  groups,
});
const identified = (id, condition, action) => ({ id, condition, action });

test("a new game starts with one empty Program group under always", () => {
  const initial = newGame().programs[0].program;
  assert.ok(
    Array.isArray(initial.groups),
    "the program is an ordered list of groups",
  );
  assert.equal(initial.groups.length, 1);
  assert.equal(initial.groups[0].name, "Program");
  assert.deepEqual(initial.groups[0].condition, ALWAYS);
  assert.deepEqual(initial.groups[0].rules, []);
  assert.ok(initial.nextGroupId > initial.groups[0].id);
  assert.ok(initial.nextRuleId > 0);
  assert.equal(Object.hasOwn(initial, "rules"), false);
});

test("group order skips false, empty and infeasible groups and then takes the first qualifying rule", () => {
  const candidate = grouped(
    group(7, below(stick, 0), [identified(71, ALWAYS, WANDER)]),
    group(5, ALWAYS, []),
    group(4, ALWAYS, [identified(42, ALWAYS, walkTo(stick))]),
    group(2, ALWAYS, [
      identified(23, below(stick, 0), WANDER),
      identified(24, ALWAYS, EXPLORE),
      identified(25, ALWAYS, WANDER),
    ]),
    group(1, ALWAYS, [identified(11, ALWAYS, WANDER)]),
  );
  let accepted;
  assert.doesNotThrow(() => {
    accepted = setProgram(newGame(), candidate).state.programs[0].program;
  });
  assert.deepEqual(chooseActivity(freshRun(), map, accepted), {
    kind: "rule",
    ruleId: 24,
    action: EXPLORE,
  });
});

test("all empty groups and an empty list of groups leave the character waiting", () => {
  for (const candidate of [
    grouped(),
    grouped(group(8, ALWAYS, []), group(3, ALWAYS, [])),
  ]) {
    let accepted;
    assert.doesNotThrow(() => {
      accepted = setProgram(newGame(), candidate).state.programs[0].program;
    });
    assert.deepEqual(chooseActivity(freshRun(), map, accepted), {
      kind: "wait",
    });
  }
});

test("identical rule contents keep distinct identities when groups and rules move", () => {
  const first = identified(91, ALWAYS, EXPLORE);
  const second = identified(17, ALWAYS, EXPLORE);
  const candidate = grouped(
    group(3, ALWAYS, [first, second]),
    group(7, ALWAYS, []),
  );
  let accepted;
  assert.doesNotThrow(() => {
    accepted = setProgram(newGame(), candidate).state.programs[0].program;
  });
  assert.equal(chooseActivity(freshRun(), map, accepted).ruleId, 91);
  const moved = {
    ...accepted,
    groups: [group(7, ALWAYS, [second]), group(3, ALWAYS, [first])],
  };
  assert.equal(chooseActivity(freshRun(), map, moved).ruleId, 17);
  assert.deepEqual(
    accepted.groups[0].rules.map((entry) => entry.id),
    [91, 17],
  );
});

test("group conditions use the same legal number, resource and item values as rules", () => {
  const conditions = [
    ALWAYS,
    below(stick, 3),
    { kind: "temperatureBelow", value: 36.5 },
    { kind: "satietyBelow", value: 50 },
    { kind: "itemBelow", item: "berry", value: 8 },
    { kind: "campfireLeftBelow", value: 20 },
    { kind: "awayFromCampfire" },
  ];
  for (const condition of conditions) {
    const candidate = grouped(
      group(5, condition, [identified(9, ALWAYS, EXPLORE)]),
    );
    let accepted;
    assert.doesNotThrow(() => {
      accepted = setProgram(newGame(), candidate).state.programs[0].program;
    });
    assert.deepEqual(accepted, candidate);
  }
});

test("group conditions refuse unknown kinds and invalid fields while accepting a legal control", () => {
  const valid = grouped(group(5, ALWAYS, []));
  assert.doesNotThrow(() => setProgram(newGame(), valid));
  for (const condition of [
    { kind: "unknown" },
    { kind: "hereBelow", resource: "unknown", value: 3 },
    { kind: "itemBelow", item: "unknown", value: 8 },
    { kind: "temperatureBelow", value: 36.55 },
    { kind: "hereBelow", resource: stick, value: -1 },
    { kind: "satietyBelow", value: Infinity },
  ]) {
    assert.throws(() =>
      setProgram(newGame(), grouped(group(5, condition, []))),
    );
  }
});

test("program identities are unique positive integers below the next identity counters", () => {
  const valid = grouped(
    group(3, ALWAYS, [identified(7, ALWAYS, EXPLORE)]),
    group(5, ALWAYS, [identified(9, ALWAYS, WANDER)]),
  );
  assert.doesNotThrow(() => setProgram(newGame(), valid));
  const corruptions = [
    (p) => {
      p.groups[1].id = 3;
    },
    (p) => {
      p.groups[1].rules[0].id = 7;
    },
    (p) => {
      p.groups[0].id = 0;
    },
    (p) => {
      p.groups[0].rules[0].id = -1;
    },
    (p) => {
      p.groups[0].rules[0].id = 1.5;
    },
    (p) => {
      p.nextGroupId = 5;
    },
    (p) => {
      p.nextRuleId = 9;
    },
    (p) => {
      p.nextRuleId = Number.MAX_SAFE_INTEGER + 1;
    },
    (p) => {
      delete p.nextGroupId;
    },
    (p) => {
      p.groups[0].groups = [];
    },
    (p) => {
      p.groups[0].rules = "bad list";
    },
    (p) => {
      p.groups = null;
    },
  ];
  for (const corrupt of corruptions) {
    const candidate = structuredClone(valid);
    corrupt(candidate);
    assert.throws(() => setProgram(newGame(), candidate));
  }
});

test("editing, deleting or transferring a started rule leaves its action running to completion", () => {
  // D-20: rule identity records the origin; the running action is its own copy.
  const candidate = grouped(
    group(3, ALWAYS, [identified(7, ALWAYS, EXPLORE)]),
    group(5, ALWAYS, []),
  );
  let state;
  assert.doesNotThrow(() => {
    state = setProgram(
      createCharacter(newKnowingGame(), "Ala").state,
      candidate,
    ).state;
  });
  state = send(state, { mapId, characterId }, 1760000000000).state;
  const original = structuredClone(state.run.current);
  const replacements = [
    grouped(group(3, ALWAYS, [identified(7, ALWAYS, WANDER)])),
    grouped(group(3, ALWAYS, [])),
    grouped(
      group(3, ALWAYS, []),
      group(5, below(stick, 0), [identified(7, ALWAYS, EXPLORE)]),
    ),
  ];
  for (const replacement of replacements) {
    const edited = setProgram(state, replacement).state;
    const beforeEnd = advanceMinutes(edited, original.endMinute - 1).state;
    assert.deepEqual(beforeEnd.run.current, original);
    const finished = advanceMinutes(beforeEnd, 1);
    assert.ok(finished.events.some((event) => event.kind === "tileRevealed"));
    assert.deepEqual(
      finished.events.find((event) => event.kind === "activityFinished")
        .activity,
      { kind: "rule", ruleId: 7, action: EXPLORE },
    );
  }
});

